        Chapter(
            "integration",
            "🔗 Integration Management (Governance Domain)",
            "Integration in PMBOK 8",
            "Knowledge domains",
            listOf(
                s("Integration in PMBOK 8", "Integration Management — now part of the PMBOK 8 Governance performance domain — is the glue that holds all other domains together. The PM's primary role IS integration: ensuring all components work coherently toward project objectives."),
                s("Project Charter — Everything to Know", tableHeaders = listOf("Aspect", "Detail"), tableRows = listOf(listOf("Purpose", "Formally authorises the project and grants the PM authority to apply organisational resources"), listOf("Created by", "The Sponsor — not the PM (PM may assist in drafting it)"), listOf("Created when", "During the Initiating Focus Area — before planning begins"), listOf("Key contents", "Project purpose and justification, measurable objectives, high-level requirements, high-level milestones, budget summary, key stakeholders, PM authority level, assumptions and constraints"), listOf("Guidance level", "High-level — refer to it when \"high-level guidance\" is needed in exam questions"))),
                s("Project Charter — Everything to Know", "Project Charter = PM's authority document. Without it, the PM has no authority. The Project Management Plan = detailed guidance. Know when to reference which.", SectionKind.KEY),
                s("Project Management Plan", "• The master integrating document — consolidates all subsidiary management plans and baselines\n• Baselines: Scope Baseline (scope statement + WBS + WBS dictionary), Schedule Baseline, Cost Baseline\n• Once formally approved, ALL changes require Integrated Change Control — even \"minor\" ones\n• It is PROGRESSIVE — updated throughout the project, not just written once and forgotten\n• Subsidiary plans: scope, schedule, cost, quality, resource, communications, risk, procurement, stakeholder management plans"),
                s("Project Management Plan", "When \"overall guidance\" or \"detailed guidance\" is needed — refer to the Project Management Plan. When only \"high-level guidance\" is needed — refer to the Project Charter.", SectionKind.TIP),
                s("Integrated Change Control — The Most Tested Process", "Change Identified\n\nRaise Change Request\n\nAssess Impact (scope/schedule/cost/quality)\n\nCCB Reviews\n\nApprove or Reject\n\nUpdate Plans & Baselines\n\nCommunicate Outcome"),
                s("Integrated Change Control — The Most Tested Process", "ALL changes go through ICC — no exceptions. Sponsor request, executive directive, \"minor\" addition — all require a formal change request and CCB approval. This is non-negotiable in PMI's world.", SectionKind.DANGER),
                s("Key Project Documents — Know the Differences", tableHeaders = listOf("Document", "Purpose", "When Updated"), tableRows = listOf(listOf("Issue Log", "Tracks problems that have ALREADY occurred or are occurring", "First thing when any issue arises — before taking action"), listOf("Risk Register", "Documents identified risks, analysis, and planned responses", "New risk identified; risk status changes; during monitoring"), listOf("Assumption Log", "Documents project assumptions and constraints throughout", "Throughout planning and execution as assumptions are identified"), listOf("Lessons Learned Register", "Captures knowledge continuously — NOT just at project close", "When issues resolved; at phase gates; and at project closure"), listOf("Change Log", "Tracks all change requests and their decisions/status", "Each time a change request is submitted or decided"), listOf("Work Performance Data (WPD)", "Raw observations from executing: % complete, costs incurred, start/finish dates", "Continuously during executing — raw input"), listOf("Work Performance Information (WPI)", "Analyzed WPD — EVM metrics, SV, CV, SPI, CPI, variances", "During M&C after analyzing WPD"), listOf("Work Performance Reports (WPR)", "Formatted communication of WPI to stakeholders", "As per communications management plan frequency"))),
                s("Key Project Documents — Know the Differences", "Data → Information → Reports: WPD (raw) → analyzed into WPI → formatted into WPR for stakeholders. This sequence is tested.", SectionKind.NOTE),
                s("Project Closure — Sequence Matters", "Complete all work\n\nVerify/validate deliverables\n\nGet FORMAL stakeholder acceptance\n\nDocument lessons learned\n\nTransition to operations\n\nRelease resources\n\nClose contracts\n\nArchive documents"),
                s("Project Closure — Sequence Matters", "Formal acceptance of deliverables MUST come BEFORE lessons learned, BEFORE transition to operations, and BEFORE disbanding the team. This sequence is frequently tested.", SectionKind.DANGER),
                s("Change Request Types — Know All Four", tableHeaders = listOf("Type", "Definition", "Example", "Requires CCB?"), tableRows = listOf(listOf("Corrective Action", "Realign project performance with the plan (fixing a problem that exists NOW)", "Adding resources to catch up on schedule", "Yes"), listOf("Preventive Action", "Reduce probability of future negative consequences (preventing a problem)", "Adding a quality checkpoint before a known risky phase", "Yes"), listOf("Defect Repair", "Fix a nonconforming product component", "Rewriting a module that failed testing", "Yes"), listOf("Update", "Modify formally controlled documents or plans", "Updating the schedule baseline after approved scope change", "Yes"))),
                s("Change Request Types — Know All Four", "ALL four types go through Integrated Change Control. Even \"preventive action\" — which sounds harmless — requires formal approval because it changes the plan.", SectionKind.WARN),
                s("Change Control Board (CCB) — Who and What", tableHeaders = listOf("Aspect", "Detail"), tableRows = listOf(listOf("Who is on the CCB?", "Defined in the change management plan — typically sponsor, PM, key stakeholders, technical leads. The PM may or may not have voting authority."), listOf("What does CCB do?", "Reviews change requests; evaluates impact analysis; approves, rejects, or defers; records decisions"), listOf("Can PM approve changes alone?", "Only if explicitly authorised in the change management plan for specific types/thresholds. Otherwise — NO."), listOf("Emergency changes?", "Change management plan should define an expedited process. Even emergencies follow a (faster) process — they do not bypass it."), listOf("Change vs. Baseline", "Approved changes update the baseline. Rejected changes are logged with rationale. All are tracked in the Change Log."))),
                s("Configuration Management vs. Change Management", "Configuration Management\n • Manages the specifications of deliverables and processes\n• Identifies which items are under configuration control\n• Tracks versions, status, and audit trail of configuration items\n• Example: Version 2.3 of the design document is the approved baseline"),
                s("Change Management", "• Manages changes to baselines and project documents\n• Governs the process of raising, evaluating, approving changes\n• Change Control Board authority defined here\n• Example: A request to move from Version 2.3 to 2.4 must go through CCB"),
                s("Project Management Information System (PMIS)", "• Automated system used to collect, store, distribute project information\n• Includes: scheduling software, work authorisation systems, configuration management systems, information collection/distribution systems\n• PMBOK 8: PMIS increasingly leverages AI for real-time tracking, analysis, and reporting\n• Common exam point: PMIS is a TOOL/TECHNIQUE, not an output. It is an EEF (part of the organisational infrastructure)."),
                s("Phase Gates / Stage Gates", tableHeaders = listOf("Aspect", "Detail"), tableRows = listOf(listOf("Definition", "Review at end of a phase where a decision is made to continue, modify, or terminate the project"), listOf("Also called", "Kill points, milestones, phase reviews, decision gates, toll gates"), listOf("Who decides?", "Typically the sponsor or steering committee — not the PM alone"), listOf("What is reviewed?", "Deliverables, performance vs plan, benefits realisation progress, business case validity, risks"), listOf("PMBOK 8 view", "Phase gates are tailoring decisions — used more in predictive; adaptive uses sprint reviews as lightweight gates"))),
            )
        ),
        Chapter(
            "scope",
            "📐 Scope Management",
            "Scope Terminology",
            "Knowledge domains",
            listOf(
                s("Scope Terminology", tableHeaders = listOf("Term", "Definition", "Exam Trap"), tableRows = listOf(listOf("Product Scope", "Features and functions that characterise the product/service/result", "Different from Project Scope"), listOf("Project Scope", "Work required to deliver the product with specified features", "Includes product scope + all PM work"), listOf("Scope Creep", "Uncontrolled addition of features without change control — caused by poor requirements and weak change control", "Very common exam topic — always a problem"), listOf("Gold Plating", "Adding extras BEYOND agreed scope — even if well-intentioned", "Avoid! Wastes resources, introduces unreviewed risk, not what customer asked for"), listOf("Progressive Elaboration", "Continuously improving project plan detail as more info becomes available", "Same concept as Rolling Wave Planning"))),
                s("Requirements Classification (PMBOK 8 — Formalised)", tableHeaders = listOf("Type", "Description", "Example"), tableRows = listOf(listOf("Business", "High-level strategic needs; WHY the project exists", "Increase market share by 15%"), listOf("Stakeholder", "Needs of a specific stakeholder or group", "CFO needs monthly cost variance reports"), listOf("Functional", "What the product MUST DO — behaviours, actions, data", "System must allow password reset via email link"), listOf("Nonfunctional", "HOW the product performs — performance, security, reliability, usability", "System must support 10,000 concurrent users with <2 sec response time"), listOf("Transition", "Temporary capabilities to move from current to desired future state", "Data migration scripts; user training program; parallel run period"))),
                s("Requirements Classification (PMBOK 8 — Formalised)", "Requirements must be: Unambiguous, Measurable, Testable, Traceable, Complete, Consistent, and Acceptable to key stakeholders — BEFORE baselining.", SectionKind.TIP),
                s("WBS — Work Breakdown Structure", "• Definition: Hierarchical decomposition of total project scope into manageable work packages\n• 100% Rule: WBS must capture 100% of project scope — nothing more, nothing less\n• Work Package: Lowest-level WBS component — what gets estimated, scheduled, and assigned to a team\n• WBS Dictionary: Detailed description of each work package — owner, resources, duration, cost estimate, acceptance criteria\n• Planning Package: WBS component with known work content but not yet decomposed (used in rolling wave planning)\n• Scope Baseline = Project Scope Statement + WBS + WBS Dictionary (all three together)"),
                s("Validate Scope vs. Control Scope — Frequently Confused", "Validate Scope\n • Process of formalising ACCEPTANCE of completed deliverables\n• Done WITH the customer / sponsor / product owner\n• Input: Verified Deliverables (from Control Quality)\n• Output: Accepted Deliverables\n• Concerned with customer ACCEPTANCE\n• Performed in M&C Focus Area"),
                s("Control Scope", "• Process of monitoring scope status and managing changes to scope baseline\n• Done by the project team continuously\n• Input: Work Performance Data\n• Output: Work Performance Information, Change Requests\n• Concerned with PREVENTING scope creep\n• Performed continuously throughout the project"),
                s("Control Scope", "Critical Sequence: Control Quality → Verified Deliverables → Validate Scope → Accepted Deliverables. Control Quality is ALWAYS performed BEFORE Validate Scope. This sequence is frequently tested.", SectionKind.DANGER),
                s("Requirements Traceability Matrix (RTM)", "• Links requirements from origin through to final deliverable — ensures nothing is missed\n• Traces: business need → business requirement → project requirement → design → test → delivery\n• Key exam point: If a requirement is not in the RTM, it is not in scope\n• Managed as part of Scope Management throughout the project lifecycle"),
                s("Requirements Elicitation Techniques", tableHeaders = listOf("Technique", "Description", "Best For"), tableRows = listOf(listOf("Interviews", "One-on-one or small group discussions to elicit requirements", "Detailed requirements from key stakeholders; sensitive topics"), listOf("Focus Groups", "Prequalified stakeholders and SMEs discuss expectations", "Understanding needs of a specific user group"), listOf("Facilitated Workshops", "Cross-functional stakeholders define requirements together (JAD sessions)", "Reconciling stakeholder differences; building consensus"), listOf("Brainstorming", "Generate ideas quickly without judgment", "Early-stage requirement discovery"), listOf("Nominal Group Technique", "Brainstorming + ranking/voting to prioritise", "Prioritising many ideas"), listOf("Delphi Technique", "Anonymous expert opinions gathered iteratively until consensus", "Avoiding groupthink; sensitive or political topics"), listOf("Observation (Job Shadowing)", "Watching users perform their work", "Discovering unstated requirements users cannot articulate"), listOf("Prototypes", "Working model of the expected product for early feedback", "Validating requirements when they are hard to describe"), listOf("Questionnaires / Surveys", "Written questions to large audience", "Many stakeholders; geographically dispersed; quantitative data"), listOf("Document Analysis", "Review existing documentation", "Regulatory requirements; existing system requirements"), listOf("Context Diagrams", "Visual model of system scope and interfaces", "Understanding system boundaries"), listOf("Benchmarking", "Compare practices to comparable organisations", "Identifying best practices"))),
                s("Prioritisation Techniques", tableHeaders = listOf("Technique", "How It Works", "Where Used"), tableRows = listOf(listOf("MoSCoW", "Must have / Should have / Could have / Won't have (this time)", "Agile backlogs; requirement prioritisation"), listOf("Kano Model", "Basic (expected) / Performance (more is better) / Excitement (delighters)", "Product feature prioritisation"), listOf("WSJF (Weighted Shortest Job First)", "Cost of Delay ÷ Job Size — highest score first", "SAFe; objective prioritisation"), listOf("Paired Comparison", "Compare each item against every other item", "Small sets of requirements"), listOf("100-Point Method", "Stakeholders distribute 100 points across requirements", "Stakeholder-driven prioritisation"), listOf("Multi-Criteria Decision Analysis", "Weighted scoring across multiple criteria", "Complex decisions with multiple factors"))),
                s("Scope in Agile vs. Predictive", tableHeaders = listOf("Aspect", "Predictive", "Agile"), tableRows = listOf(listOf("Scope definition", "Fully defined upfront in scope statement + WBS", "Emerges through backlog refinement; high-level vision upfront"), listOf("Scope baseline", "Fixed; changes via formal change control", "Product backlog is dynamic; PO reprioritises continuously"), listOf("Scope validation", "Formal acceptance at milestones", "Sprint review acceptance of increment"), listOf("Scope creep control", "Change control process; CCB", "Sprint Goal protection; only PO changes backlog"), listOf("Decomposition", "WBS → work packages", "Theme → Epic → Story → Task"), listOf("Requirements doc", "Requirements documentation + RTM", "User stories with acceptance criteria"))),
                s("Definition of Ready vs. Definition of Done", "Definition of Ready (DoR)\n • Criteria a backlog item must meet BEFORE it can be pulled into a sprint\n• Example: story is clear, estimated, acceptance criteria defined, dependencies resolved\n• Prevents teams from starting work on poorly understood items\n• Not an official Scrum artifact but widely used"),
                s("Definition of Done (DoD)", "• Criteria an item must meet to be considered COMPLETE\n• Example: code reviewed, tested, documented, deployed to staging\n• Ensures consistent quality across all increments\n• Official Scrum artifact commitment for the Increment"),
            )
        ),
        Chapter(
            "schedule",
            "📅 Schedule Management",
            "Schedule Development Flow",
            "Knowledge domains",
            listOf(
                s("Schedule Development Flow", "Plan Schedule Mgmt\n\nDefine Activities\n\nSequence Activities\n\nEstimate Durations\n\nDevelop Schedule\n\nControl Schedule"),
                s("Critical Path Method (CPM)", "• Critical Path: The LONGEST path through the network diagram — determines the earliest possible project completion date\n• Total Float/Slack: Amount of time an activity can be delayed without delaying the project end date\n• Critical Path activities = ZERO total float — any delay to them delays the entire project\n• Free Float: Time an activity can delay without delaying its immediate SUCCESSOR (may be different from total float)\n• Negative Float: Project is already behind schedule — critical path activities are late\n• Near-critical path: Paths with very low float — monitor closely as they could become critical"),
                s("Critical Path Method (CPM)", "If a question asks which activities to prioritise — ALWAYS prioritise critical path activities (zero float) first. Non-critical activities have slack that can absorb minor delays.", SectionKind.KEY),
                s("Logical Relationship Types", tableHeaders = listOf("Type", "Abbrev.", "Meaning", "Most Common?"), tableRows = listOf(listOf("Finish-to-Start", "FS", "Successor cannot START until predecessor FINISHES", "✅ Most common — default assumption"), listOf("Finish-to-Finish", "FF", "Successor cannot FINISH until predecessor FINISHES", "Common in testing scenarios"), listOf("Start-to-Start", "SS", "Successor cannot START until predecessor STARTS", "Common in parallel work"), listOf("Start-to-Finish", "SF", "Successor cannot FINISH until predecessor STARTS", "Rare — almost never used"))),
                s("Lead and Lag", "Lead (Negative Lag — Overlap)\n • Activity B starts BEFORE Activity A is complete\n• Creates an overlap between activities\n• Shown as negative lag in scheduling tools\n• REDUCES overall project duration\n• Example: Landscaping starts 2 weeks before punch list completion (FS –2 weeks)"),
                s("Lag (Waiting Time — Delay)", "• A mandatory wait BETWEEN activities\n• Successor must wait after predecessor starts or finishes\n• EXTENDS overall project duration\n• Duration estimates do NOT include lead or lag time\n• Example: Editing starts 15 days after writing begins (SS +15 days)"),
                s("Schedule Compression Techniques", tableHeaders = listOf("Technique", "What It Does", "Cost Impact", "Risk Impact", "Applied To", "When to Use"), tableRows = listOf(listOf("Crashing", "Add resources (people, equipment, overtime) to shorten duration of critical path activities", "Increases cost — sometimes significantly", "Moderate — more people = more coordination", "Critical path activities ONLY — no value on non-critical", "When schedule MUST be shortened and budget allows"), listOf("Fast Tracking", "Perform sequential activities in parallel that were originally planned sequentially", "No direct additional cost", "Increases rework risk — if earlier work changes, later parallel work may need redoing", "Only where logical overlap is possible", "When schedule must be shortened without adding cost"))),
                s("Schedule Compression Techniques", "Always consider Fast Tracking BEFORE Crashing — it does not add direct cost. Use Crashing only when fast tracking is not possible or insufficient.", SectionKind.TIP),
                s("Resource Leveling vs. Resource Smoothing", tableHeaders = listOf("Resource Leveling", "Resource Smoothing"), tableRows = listOf(listOf("Purpose", "Resolve resource over-allocation or conflicts", "Optimise resource usage within float available"), listOf("Effect on Schedule", "MAY extend the schedule", "Does NOT extend the schedule beyond current dates"), listOf("Float", "May consume total float and change critical path", "Only uses available float — critical path unchanged"), listOf("When Used", "When resources are constrained and overallocated", "When schedule dates are fixed but resource usage needs smoothing"))),
                s("Estimation Techniques", tableHeaders = listOf("Technique", "Method", "Accuracy Range", "When to Use"), tableRows = listOf(listOf("Analogous", "Historical data from similar projects; expert judgment; top-down approach", "Low: –25% to +75%", "Early project; when little detail is available; quick estimate needed"), listOf("Parametric", "Algorithm using historical data × project parameters (e.g., cost per unit × quantity)", "Medium to High", "When measurable, repeatable parameters exist (construction, software features)"), listOf("Three-Point (PERT)", "Optimistic (O), Most Likely (M), Pessimistic (P) — accounts for uncertainty", "High", "High uncertainty; insufficient historical data; risk-aware estimation"), listOf("Bottom-Up", "Estimate each work package individually and aggregate upward", "Highest: –5% to +10%", "When detailed scope is defined; most accurate but most time-consuming"))),
                s("Estimation Techniques", "Estimation Formulas"),
                s("Rolling Wave Planning", "• Near-term work is planned in detail; far future work is planned at a higher level\n• Detail is added progressively as the project moves forward and more information becomes available\n• NOT a sign of poor planning — it is deliberately embraced in uncertain environments\n• Used in both predictive (for future phases) and adaptive (sprint-by-sprint) approaches\n• Also called Progressive Elaboration when referring to the planning process itself"),
                s("Forward and Backward Pass — Step by Step", "The Critical Path Method uses forward and backward passes to calculate early/late dates and float:"),
                s("Forward and Backward Pass — Step by Step", tableHeaders = listOf("Step", "Calculation", "What You Get"), tableRows = listOf(listOf("Forward Pass", "ES = max(EF of all predecessors). EF = ES + Duration − 1 (or ES + Duration if using 0-based)", "Early Start (ES) and Early Finish (EF) for every activity"), listOf("Backward Pass", "LF = min(LS of all successors). LS = LF − Duration + 1", "Late Start (LS) and Late Finish (LF) for every activity"), listOf("Total Float", "TF = LS − ES (or LF − EF — same result)", "How much an activity can slip without delaying project"), listOf("Free Float", "FF = min(ES of successors) − EF", "How much an activity can slip without delaying its immediate successor"))),
                s("Forward and Backward Pass — Step by Step", "Worked Example (0-based convention):\n\nActivities: A (dur 3) → B (dur 4) → D (dur 2). A (dur 3) → C (dur 6) → D (dur 2).\n\nForward Pass:\n\nA: ES=0, EF=3\n\nB: ES=3, EF=7  |  C: ES=3, EF=9\n\nD: ES = max(7, 9) = 9, EF = 11\n\nProject duration = 11\n\nBackward Pass (start from D: LF=11):\n\nD: LF=11, LS=9\n\nB: LF=9, LS=5  |  C: LF=9, LS=3\n\nA: LF = min(5, 3) = 3, LS=0\n\nFloat:\n\nA: LS−ES = 0−0 = 0 (critical)\n\nB: LS−ES = 5−3 = 2 (has 2 days float)\n\nC: LS−ES = 3−3 = 0 (critical)\n\nD: LS−ES = 9−9 = 0 (critical)\n\nCritical Path: A → C → D (11 days). B has 2 days float."),
                s("Dependency Types", tableHeaders = listOf("Type", "Definition", "Example"), tableRows = listOf(listOf("Mandatory (Hard Logic)", "Inherent in the nature of work; physically or legally required", "Foundation must be poured before walls are built"), listOf("Discretionary (Soft/Preferred Logic)", "Based on best practice or team preference; can be changed", "Team prefers to complete design before starting any coding"), listOf("External", "Dependency on non-project activities outside team control", "Waiting for government permit approval"), listOf("Internal", "Dependency within the project team's control", "Testing cannot begin until development completes"))),
                s("Dependency Types", "When fast-tracking, look for DISCRETIONARY dependencies to overlap — mandatory dependencies cannot be fast-tracked.", SectionKind.TIP),
                s("Schedule Tools and Charts", tableHeaders = listOf("Tool", "Purpose", "Key Feature"), tableRows = listOf(listOf("Gantt Chart (Bar Chart)", "Visual timeline of activities", "Shows start/end dates, durations, overlaps — easy for stakeholders"), listOf("Milestone Chart", "Shows only major milestones", "High-level view for executives; zero-duration events"), listOf("Network Diagram (PDM)", "Shows logical relationships between activities", "Used for critical path analysis; precedence diagramming method"), listOf("Schedule Baseline", "Approved version of the schedule", "Used to measure actual performance against plan"), listOf("Resource Histogram", "Shows resource usage over time", "Identifies over-allocation and under-utilisation"), listOf("Monte Carlo Simulation", "Probabilistic schedule modelling", "Shows probability of finishing by various dates"))),
                s("Agile Scheduling Concepts", tableHeaders = listOf("Concept", "Definition", "Formula/Usage"), tableRows = listOf(listOf("Timebox", "Fixed duration for an activity or iteration; scope flexes, time does not", "Sprints (1–4 weeks), Daily Scrum (15 min)"), listOf("Velocity", "Story points completed per sprint", "Forecast: Remaining points ÷ velocity = sprints remaining"), listOf("Release Planning", "Determining which features go in which release", "Based on velocity and backlog priority"), listOf("Iteration Burndown", "Shows work remaining in a sprint", "Ideal line vs actual line — gap = ahead/behind"), listOf("Release Burnup", "Shows work completed toward release + total scope", "Scope line moves up when scope added"), listOf("On-demand scheduling", "Kanban — pull work when capacity available", "No timeboxes; continuous flow"))),
                s("Agile Scheduling Concepts", "Agile Forecasting"),
            )
        ),
        Chapter(
            "cost",
            "💰 Cost Management & Earned Value (EVM)",
            "Key Cost Concepts",
            "Knowledge domains",
            listOf(
                s("Danger", "EVM questions appear in almost every PMP exam. You MUST know ALL formulas cold AND understand what each result means. Practice with numbers until it becomes automatic.", SectionKind.DANGER),
                s("Key Cost Concepts", tableHeaders = listOf("Term", "Definition", "Memory Aid"), tableRows = listOf(listOf("BAC — Budget at Completion", "Total approved budget for the entire project", "The \"target\" — what you planned to spend in total"), listOf("PV — Planned Value", "Authorised budget for scheduled work at a specific point in time (BCWS)", "What you PLANNED to accomplish by now (in \$)"), listOf("EV — Earned Value", "Planned value of work actually completed: EV = % Complete × BAC", "What you have EARNED by completing work (in \$)"), listOf("AC — Actual Cost", "Actual cost incurred for work performed (ACWP)", "What you ACTUALLY SPENT so far"), listOf("EAC — Estimate at Completion", "Projected total cost at project completion (forecast)", "How much the project will COST IN TOTAL"), listOf("ETC — Estimate to Complete", "Expected cost to finish all REMAINING work", "How much MORE you need to spend"), listOf("VAC — Variance at Completion", "BAC − EAC — projected over/under budget at end", "Positive = under budget. Negative = over budget at end."), listOf("TCPI — To-Complete Performance Index", "Cost efficiency needed to meet financial target", "How HARD you must work from here to meet BAC or EAC"))),
                s("Key Cost Concepts", "EVM Formulas — All of Them"),
                s("Quick Interpretation Table", tableHeaders = listOf("Metric", "Positive ✅", "Zero = On Track", "Negative ❌"), tableRows = listOf(listOf("SV (EV−PV)", "Ahead of schedule", "Exactly on schedule", "Behind schedule"), listOf("CV (EV−AC)", "Under budget", "Exactly on budget", "Over budget"), listOf("SPI (EV/PV)", ">1.0 ahead of schedule", "=1.0 on schedule", "<1.0 behind schedule"), listOf("CPI (EV/AC)", ">1.0 under budget", "=1.0 on budget", "<1.0 over budget"), listOf("TCPI", "<1.0 easier than current rate", "=1.0 maintain current efficiency", ">1.0 must work MORE efficiently than now"), listOf("VAC (BAC−EAC)", "Positive = will finish under budget", "Negative = will finish over budget"))),
                s("Fully Worked EVM Example", "Scenario: Project BAC = \$200,000. After 6 months, 50% should be complete (PV = \$100,000). Actual work completed = 40% (EV = \$80,000). Actual cost = \$110,000 (AC).\n\nEV = 40% × \$200,000 = \$80,000\n\nSV = EV − PV = 80,000 − 100,000 = −\$20,000 → Behind schedule\n\nCV = EV − AC = 80,000 − 110,000 = −\$30,000 → Over budget\n\nSPI = EV / PV = 80,000 / 100,000 = 0.80 → Only 80% schedule efficiency\n\nCPI = EV / AC = 80,000 / 110,000 = 0.727 → Only 72.7 cents of value per \$1 spent\n\nEAC (typical) = BAC / CPI = 200,000 / 0.727 = \$275,104\n\nETC = EAC − AC = 275,104 − 110,000 = \$165,104 → Still need to spend this much\n\nVAC = BAC − EAC = 200,000 − 275,104 = −\$75,104 → Will be ~\$75K over budget at end\n\nTCPI (to meet BAC) = (200,000 − 80,000) / (200,000 − 110,000) = 120,000 / 90,000 = 1.33 → Must be 33% more efficient than current rate — very difficult"),
                s("Reserve Analysis", "Contingency Reserve\n • For known unknowns (identified risks in the risk register)\n• Managed by the PM — within PM's authority\n• Part of the project cost baseline\n• Triggered when a risk response plan is activated\n• Shown in cost baseline and schedule baseline"),
                s("Management Reserve", "• For unknown unknowns (unforeseeable risks)\n• Controlled by management/sponsor — NOT the PM\n• NOT part of PM's baseline — separate from baseline\n• Requires management approval to access\n• Not included in Earned Value calculations"),
                s("Management Reserve", "If a PM uses management reserve without approval — that is a problem. If a PM uses contingency reserve for an identified risk — that is correct. Know the difference.", SectionKind.WARN),
                s("Cost Estimation Techniques", tableHeaders = listOf("Technique", "Accuracy", "Notes"), tableRows = listOf(listOf("ROM (Rough Order of Magnitude)", "−25% to +75%", "Very early estimate; minimal information; used for feasibility"), listOf("Budget Estimate", "−10% to +25%", "Based on partial design or scope; better information"), listOf("Definitive Estimate", "−5% to +10%", "Detailed scope and design available; highest accuracy"), listOf("Parametric Estimating", "Varies", "Algorithm-based; highly accurate when historical data is good"))),
                s("EAC — Which Formula When?", tableHeaders = listOf("Scenario in Question", "Use This EAC Formula", "Why"), tableRows = listOf(listOf("\"Current variances are typical / expected to continue\"", "EAC = BAC / CPI", "Assumes current cost efficiency continues for the rest"), listOf("\"Original estimate was flawed\" or \"assumptions were wrong\"", "EAC = AC + Bottom-up ETC", "Re-estimate remaining work from scratch"), listOf("\"Current variances are atypical / one-time / will not recur\"", "EAC = AC + (BAC − EV)", "Remaining work will be done at PLANNED rate"), listOf("\"Both schedule and cost performance affect the estimate\"", "EAC = AC + (BAC − EV) / (CPI × SPI)", "Accounts for both indices"))),
                s("EAC — Which Formula When?", "The exam ALWAYS gives you a clue about which formula to use — read the scenario for words like \"typical,\" \"atypical,\" \"flawed,\" or \"both cost and schedule.\" If no clue is given, default to BAC / CPI.", SectionKind.KEY),
                s("Second Worked Example — Recovering Project", "Scenario: BAC = \$500,000. Project is 60% complete. PV = \$350,000. AC = \$280,000.\n\nEV = 60% × 500,000 = \$300,000\n\nSV = 300,000 − 350,000 = −\$50,000 (behind schedule)\n\nCV = 300,000 − 280,000 = +\$20,000 (under budget!)\n\nSPI = 300,000 / 350,000 = 0.857 (behind schedule)\n\nCPI = 300,000 / 280,000 = 1.071 (under budget — spending efficiently)\n\nEAC (typical) = 500,000 / 1.071 = \$466,853\n\nVAC = 500,000 − 466,853 = +\$33,147 (will finish under budget)\n\nTCPI (to BAC) = (500,000 − 300,000) / (500,000 − 280,000) = 200,000 / 220,000 = 0.909\n\nInterpretation: This project is behind schedule but under budget. CPI > 1 means cost performance is good. TCPI < 1 means the team can afford to spend slightly more per unit of work than currently and still meet BAC. The schedule is the concern — consider fast-tracking (no cost) or crashing (has budget headroom)."),
                s("Cost Baseline vs. Budget", "Activity Cost Estimates\n\n+ Work Package Contingency\n\n= Work Package Cost\n\n+ Control Account Contingency\n\n= Cost Baseline\n\n+ Management Reserve\n\n= Project Budget"),
                s("Cost Baseline vs. Budget", tableHeaders = listOf("Component", "Included In", "Controlled By"), tableRows = listOf(listOf("Activity cost estimates", "Cost baseline", "PM"), listOf("Contingency reserve", "Cost baseline", "PM"), listOf("Management reserve", "Project budget (NOT cost baseline)", "Sponsor/management"))),
                s("Cost Baseline vs. Budget", "Exam trap: \"Which is NOT part of the cost baseline?\" → Management Reserve. The cost baseline is what EVM measures against. Management reserve sits above the baseline.", SectionKind.WARN),
                s("Financial Analysis for Project Selection", tableHeaders = listOf("Metric", "Formula / Definition", "Decision Rule"), tableRows = listOf(listOf("NPV (Net Present Value)", "Sum of discounted future cash flows minus initial investment", "Higher NPV is better; NPV > 0 = worthwhile"), listOf("IRR (Internal Rate of Return)", "Discount rate at which NPV = 0", "Higher IRR is better; compare to hurdle rate"), listOf("Payback Period", "Time to recover the initial investment", "Shorter is better; ignores time value of money"), listOf("BCR (Benefit-Cost Ratio)", "PV of Benefits ÷ PV of Costs", "BCR > 1 = benefits exceed costs; higher is better"), listOf("ROI (Return on Investment)", "(Gain − Cost) ÷ Cost × 100%", "Higher is better"), listOf("Opportunity Cost", "Value of the next best alternative NOT chosen", "Lower opportunity cost is better"), listOf("Sunk Cost", "Money already spent that cannot be recovered", "NEVER consider sunk cost in forward decisions"))),
                s("Depreciation (Occasionally Tested)", tableHeaders = listOf("Method", "Description"), tableRows = listOf(listOf("Straight-Line", "Same amount depreciated each year: (Cost − Salvage) ÷ Useful Life"), listOf("Accelerated (Double Declining Balance)", "More depreciation in early years; less later"), listOf("Sum-of-Years-Digits", "Another accelerated method; weights early years more heavily"))),
            )
        ),
        Chapter(
            "quality",
            "✅ Quality Management (Governance Domain)",
            "Quality Philosophy",
            "Knowledge domains",
            listOf(
                s("Quality Philosophy", "• Prevention over inspection — build quality in from the start; it is always cheaper to prevent defects than to find and fix them\n• Customer satisfaction — meet or exceed stated AND unstated customer expectations. Fitness for use.\n• Continuous improvement (Kaizen) — always seek ways to improve processes and outputs; never stop improving\n• Cost of Quality: Money spent on achieving quality AND money lost from lack of quality — both must be managed\n• Quality is PLANNED in — it is not added at the end through testing and inspection alone"),
                s("Cost of Quality (COQ) — Know All 4 Categories", tableHeaders = listOf("Category", "Sub-type", "Examples", "PMI Preference"), tableRows = listOf(listOf("Conformance", "Prevention", "Training, quality planning, process design, standards development, tool calibration", "✅ Preferred — cheapest in the long run"), listOf("Conformance", "Appraisal", "Testing, inspections, peer reviews, walkthroughs, quality audits", "Necessary — find defects before delivery"), listOf("Non-Conformance", "Internal Failure", "Rework, scrap, defect repair found BEFORE delivery to customer", "Expensive — avoid through prevention"), listOf("Non-Conformance", "External Failure", "Warranty claims, customer complaints, liability, recalls, lost business", "Most expensive — must be eliminated"))),
                s("Cost of Quality (COQ) — Know All 4 Categories", "Prevention costs are ALWAYS preferred. Internal failure is better than external failure. The cheapest time to fix a defect is when it is prevented. The most expensive is when the customer finds it.", SectionKind.KEY),
                s("Quality Processes", tableHeaders = listOf("Process", "Focus Area", "What It Does", "Key Output"), tableRows = listOf(listOf("Plan Quality Management", "Planning", "Define quality standards and how to achieve/verify them", "Quality Management Plan, Quality Metrics, Test and Evaluation Documents"), listOf("Manage Quality", "Executing", "Translate quality plan into activities; perform quality audits; process analysis", "Quality Reports, Change Requests (process improvement)"), listOf("Control Quality", "M&C", "Inspect DELIVERABLES; verify they meet quality requirements; produce verified deliverables", "Verified Deliverables, Quality Control Measurements, Change Requests"))),
                s("7 Basic Quality Tools", "Cause & Effect (Fishbone / Ishikawa)"),
                s("Control Chart — Key Terms", tableHeaders = listOf("Term", "Definition", "Exam Point"), tableRows = listOf(listOf("Mean", "Average value — centre line on control chart", "Baseline for comparison"), listOf("Control Limits", "±3 standard deviations from mean — set by the PROCESS", "Not set by customer — set by process capability"), listOf("Specification Limits", "Customer requirements — set by the CUSTOMER", "May be inside or outside control limits"), listOf("Rule of Seven", "7+ consecutive points on ONE SIDE of mean = process out of control", "Even if all within limits — investigate!"), listOf("Assignable Cause", "Variation from specific, identifiable cause — requires investigation", "Must be found and eliminated"), listOf("Common Cause", "Natural variation inherent in the process — acceptable if within limits", "If within limits — acceptable"))),
                s("Control Chart — Key Terms", "A process can be WITHIN control limits but still OUT OF CONTROL (Rule of Seven). Out of control = non-random pattern, NOT necessarily exceeding limits.", SectionKind.WARN),
                s("Quality Management Concepts — Deeper", tableHeaders = listOf("Concept", "Definition", "Exam Angle"), tableRows = listOf(listOf("Quality vs. Grade", "Quality = degree to which characteristics fulfil requirements. Grade = category based on features.", "Low grade is acceptable (basic phone); low quality is NOT (broken phone)"), listOf("Precision vs. Accuracy", "Precision = consistency of measurements (tight cluster). Accuracy = closeness to true value.", "Can be precise but inaccurate (consistently wrong). Both needed."), listOf("Attribute Sampling", "Result conforms or does not (pass/fail)", "Used for go/no-go inspection"), listOf("Variable Sampling", "Result measured on a continuous scale (e.g., 4.7mm)", "Used for measuring degree of conformance"), listOf("Tolerance", "Specified range of acceptable results", "Set by requirements / customer"), listOf("Control Limits", "Boundaries of common variation in a stable process", "Set by the PROCESS (±3σ), not the customer"), listOf("Statistical Sampling", "Inspecting a subset rather than 100%", "Reduces cost of quality; sample size determined by confidence needed"))),
                s("Quality Gurus and Their Contributions", tableHeaders = listOf("Person", "Contribution", "Key Idea"), tableRows = listOf(listOf("W. Edwards Deming", "14 Points; PDCA cycle; 85% of quality problems are management's responsibility", "Plan-Do-Check-Act; drive out fear; continuous improvement"), listOf("Joseph Juran", "Quality Trilogy; \"fitness for use\"; Pareto principle applied to quality", "Planning, Control, Improvement; 80/20 rule"), listOf("Philip Crosby", "Zero Defects; \"quality is free\"; conformance to requirements", "Cost of quality — prevention is cheaper than failure"), listOf("Kaoru Ishikawa", "Fishbone diagram; quality circles; 7 basic quality tools", "Root cause analysis; employee involvement"), listOf("Genichi Taguchi", "Design of Experiments; loss function", "Quality should be designed in, not inspected in"))),
                s("PDCA / Continuous Improvement Cycle", tableHeaders = listOf("Step", "Activity"), tableRows = listOf(listOf("Plan", "Identify the improvement opportunity; plan the change"), listOf("Do", "Implement the change on a small scale (pilot)"), listOf("Check", "Measure results; compare to expectations"), listOf("Act", "If successful, standardise; if not, learn and re-plan"))),
                s("Additional Quality Tools", tableHeaders = listOf("Tool", "Purpose"), tableRows = listOf(listOf("Affinity Diagram", "Groups large numbers of ideas into natural categories"), listOf("Process Decision Program Chart (PDPC)", "Identifies what could go wrong in a plan and builds countermeasures"), listOf("Interrelationship Digraph", "Shows cause-effect relationships among multiple factors"), listOf("Tree Diagram", "Systematic breakdown of a topic into detailed components (like WBS for quality)"), listOf("Matrix Diagram", "Shows relationships between two or more sets of factors"), listOf("Prioritisation Matrix", "Ranks options against weighted criteria"), listOf("Design of Experiments (DOE)", "Statistical method to identify which variables most affect outcomes"), listOf("Failure Mode and Effects Analysis (FMEA)", "Identifies potential failures, their causes, effects, and prioritises by risk"))),
                s("Quality in Agile", "• Definition of Done: Team-agreed quality criteria every increment must meet\n• Test-Driven Development (TDD): Write tests first, then code to pass the tests\n• Continuous Integration: Code merged and tested frequently — catches defects early\n• Pair Programming: Two developers; one codes, one reviews in real time\n• Refactoring: Improving code structure without changing behaviour\n• Retrospectives: Regular process quality improvement\n• Technical Debt: Shortcuts taken that must be \"repaid\" later — should be tracked and managed"),
            )
        ),
        Chapter(
            "risk",
            "⚠️ Risk Management",
            "Risk Management Process Flow",
            "Knowledge domains",
            listOf(
                s("Risk Management Process Flow", "Plan Risk Management\n\nIdentify Risks\n\nQualitative Analysis\n\nQuantitative Analysis (if needed)\n\nPlan Responses\n\nImplement Responses\n\nMonitor Risks"),
                s("Risk Management Process Flow", "Risk management is CONTINUOUS throughout the project — not a one-time activity. New risks emerge during execution and must be captured, analyzed, and responded to.", SectionKind.KEY),
                s("Qualitative vs. Quantitative Risk Analysis", tableHeaders = listOf("Qualitative Analysis", "Quantitative Analysis"), tableRows = listOf(listOf("Purpose", "PRIORITISE risks by relative probability and impact — which risks matter most?", "NUMERICALLY model the effect of risks on project objectives"), listOf("When Done", "ALL projects — done first, before quantitative", "Only for LARGE, COMPLEX, HIGH-STAKES projects — not always done"), listOf("Method", "Probability × Impact Matrix (P×I); Risk Urgency; Risk Categorisation", "Monte Carlo Simulation; Decision Trees; Sensitivity Analysis (Tornado Chart)"), listOf("Accuracy", "Relative (High/Medium/Low)", "Specific numbers (probability of finishing by date, cost at risk)"), listOf("Output", "Prioritised risk list — which risks to plan responses for", "Statistical range of possible outcomes; contingency reserve amount"))),
                s("Qualitative vs. Quantitative Risk Analysis", "Expected Monetary Value (EMV)"),
                s("Risk Response Strategies — Threats AND Opportunities", tableHeaders = listOf("Strategy", "For THREATS (Negative Risks)", "For OPPORTUNITIES (Positive Risks)"), tableRows = listOf(listOf("Escalate", "Risk is beyond PM's authority — notify and involve management", "Opportunity beyond PM's scope — notify management to act"), listOf("Avoid / Exploit", "ELIMINATE the cause of the threat entirely — change plan to remove it", "ENSURE the opportunity definitely occurs — take definitive action to guarantee it"), listOf("Transfer / Share", "Shift financial or operational impact to a THIRD PARTY (insurance, outsourcing)", "PARTNER with another entity to share the benefit and the effort"), listOf("Mitigate / Enhance", "Reduce PROBABILITY or IMPACT (or both) of the threat", "Increase PROBABILITY or IMPACT (or both) of the opportunity"), listOf("Accept — Active", "Create a CONTINGENCY PLAN that executes if the risk occurs", "Create a PLAN TO CAPITALISE if the opportunity arises"), listOf("Accept — Passive", "Acknowledge but take NO action — monitor only", "Acknowledge but take NO action — monitor only"))),
                s("Key Risk Terms", tableHeaders = listOf("Term", "Definition"), tableRows = listOf(listOf("Risk Appetite", "The level of uncertainty an organisation is WILLING to accept in pursuit of its objectives — documented in the Risk Management Plan"), listOf("Risk Tolerance", "The SPECIFIC AMOUNT of risk a stakeholder or organisation is willing to accept — more granular than appetite"), listOf("Risk Threshold", "The TRIGGER POINT for action — below threshold: can accept; above: must respond with a defined strategy"), listOf("Secondary Risk", "A NEW risk that emerges AS A DIRECT RESULT of implementing a risk response strategy"), listOf("Residual Risk", "Risk that REMAINS after risk responses have been fully implemented — must be documented and monitored"), listOf("Workaround", "UNPLANNED response to a risk event — used when no contingency plan exists for that risk"), listOf("Fallback Plan", "BACKUP response used when the PRIMARY risk response proves inadequate or fails"), listOf("Risk Register", "Documents ALL identified risks, their characteristics, analysis results, and planned responses"), listOf("Risk Report", "Provides summary info on individual risks and overall project risk — separate from the register"), listOf("Tornado Chart", "Horizontal bar chart showing which risks have the greatest SENSITIVITY IMPACT on project objectives — widest bars = most influential risks"))),
                s("Monitor Risks — Key Inputs and Outputs (PMBOK 8 ITTO)", "Inputs\n • Project management plan (risk management plan)\n• Issue log, Lessons learned register\n• Risk register, Risk report\n• Work performance data and reports"),
                s("Outputs", "• Work performance information\n• Change requests\n• Project management plan updates\n• Project document updates: Assumption log, Issue log, Lessons learned register, Risk register, Risk report"),
                s("Risk Identification Techniques", tableHeaders = listOf("Technique", "Description", "Best For"), tableRows = listOf(listOf("Brainstorming", "Team generates risk ideas freely", "Initial comprehensive identification"), listOf("Checklists", "Based on historical info and lessons learned", "Common risks in similar projects"), listOf("Interviews", "Experienced stakeholders and SMEs share risks", "Deep expertise; sensitive topics"), listOf("Root Cause Analysis", "Identify underlying causes of risks", "Grouping risks by cause"), listOf("SWOT Analysis", "Strengths, Weaknesses (internal); Opportunities, Threats (external)", "Both positive and negative risks"), listOf("Assumption & Constraint Analysis", "Test validity of assumptions — each false assumption is a risk", "Project planning; uncertain premises"), listOf("Document Analysis", "Review plans, contracts, requirements for inconsistencies", "Finding gaps and conflicts"), listOf("Prompt Lists", "Predetermined categories to stimulate thinking (PESTLE, TECOP, VUCA)", "Ensuring coverage of all risk categories"), listOf("Delphi Technique", "Anonymous expert consensus over rounds", "Avoiding bias and groupthink"))),
                s("Prompt Lists — PESTLE and TECOP", "PESTLE (External)\n • Political\n• Economic\n• Social\n• Technological\n• Legal\n• Environmental"),
                s("TECOP (Project)", "• Technical\n• Environmental\n• Commercial\n• Operational\n• Political"),
                s("Risk Breakdown Structure (RBS)", "Hierarchical representation of risks by category — like a WBS for risks. Typical top-level categories:"),
                s("Risk Breakdown Structure (RBS)", tableHeaders = listOf("Category", "Examples"), tableRows = listOf(listOf("Technical", "Requirements, technology, complexity, interfaces, performance, quality"), listOf("External", "Subcontractors, regulatory, market, customer, weather"), listOf("Organisational", "Dependencies, resources, funding, prioritisation"), listOf("Project Management", "Estimating, planning, controlling, communication"))),
                s("Probability and Impact Matrix — Worked Example", "Risk Score = Probability × Impact\n\nScale: Probability 1–5 (1=very low, 5=very high). Impact 1–5 (1=negligible, 5=catastrophic).\n\nRisk A: P=4, I=5 → Score = 20 (HIGH — must respond)\n\nRisk B: P=2, I=3 → Score = 6 (MEDIUM — monitor)\n\nRisk C: P=5, I=1 → Score = 5 (LOW — accept)\n\nRisk D: P=1, I=5 → Score = 5 (LOW score BUT high impact — consider a contingency plan)\n\nKey insight: Risk D has the same score as Risk C, but a catastrophic impact (even at low probability) often warrants a contingency plan. Do not rely purely on the score — use judgment."),
                s("Decision Tree Analysis — Worked Example", "Scenario: Build a new facility or upgrade the existing one?\n\nOption 1: Build New — Cost \$200K\n\n  60% chance of high demand → revenue \$500K\n\n  40% chance of low demand → revenue \$200K\n\n  EMV = (0.6 × 500K) + (0.4 × 200K) − 200K = 300K + 80K − 200K = +\$180K\n\nOption 2: Upgrade Existing — Cost \$80K\n\n  60% chance of high demand → revenue \$300K\n\n  40% chance of low demand → revenue \$150K\n\n  EMV = (0.6 × 300K) + (0.4 × 150K) − 80K = 180K + 60K − 80K = +\$160K\n\nDecision: Build New has higher EMV (+\$180K vs +\$160K). Choose Build New."),
                s("Monte Carlo Simulation", "• Runs thousands of iterations using random values from probability distributions for each activity\n• Output: probability distribution of project completion date or cost (e.g., \"80% confident of finishing by June 15\")\n• Reveals which activities are most likely to end up on the critical path (criticality index)\n• Used in quantitative risk analysis for large/complex projects\n• Result is an S-curve showing cumulative probability"),
                s("Risk Management in Agile", tableHeaders = listOf("Practice", "How It Manages Risk"), tableRows = listOf(listOf("Short iterations", "Frequent delivery reduces the risk of building the wrong thing"), listOf("Sprint reviews", "Regular stakeholder feedback catches problems early"), listOf("Backlog prioritisation", "Highest-risk, highest-value items done first (risk-adjusted backlog)"), listOf("Spikes", "Time-boxed research to reduce technical uncertainty before committing"), listOf("Retrospectives", "Process risks identified and addressed each sprint"), listOf("Daily Scrum", "Impediments surfaced within 24 hours"), listOf("Risk burndown chart", "Tracks total risk exposure over sprints — should trend downward"))),
            )
        ),
        Chapter(
            "stakeholders",
            "👥 Stakeholder & Communications Management",
            "Stakeholder Engagement Levels",
            "Knowledge domains",
            listOf(
                s("Stakeholder Engagement Levels", tableHeaders = listOf("Level", "Description", "PM Goal", "Engagement Strategy"), tableRows = listOf(listOf("Unaware", "Not aware of the project or its potential impacts", "Move to Supportive or higher", "Proactive information sharing; education about project benefits and impacts"), listOf("Resistant", "Aware but OPPOSED — will not support the project or its outcomes", "Move to Neutral or higher", "Understand root concerns; engage in dialogue; address specific objections; involve in decisions"), listOf("Neutral", "Aware but neither supportive nor opposed — passive stance", "Move to Supportive", "Clarify benefits and value; involve in planning to build ownership and investment"), listOf("Supportive", "Aware and supportive — will support but not actively champion", "Maintain; leverage", "Maintain regular communication; leverage their support; keep them engaged"), listOf("Leading", "Actively CHAMPIONING the project — highly engaged advocate", "Maintain; empower", "Empower and enable their advocacy; use as change agents; co-create solutions"))),
                s("Stakeholder Engagement Levels", "The Stakeholder Engagement Assessment Matrix shows Current (C) vs Desired (D) level for each stakeholder. The GAP between C and D determines how much engagement effort is needed.", SectionKind.NOTE),
                s("Stakeholder Analysis Tools", "• Power/Interest Grid: High power + High interest = Manage Closely. High power + Low interest = Keep Satisfied. Low power + High interest = Keep Informed. Low power + Low interest = Monitor.\n• Stakeholder Register: Documents identification, assessment, classification — interests, involvement, interdependencies, influence, potential impact on project success\n• Stakeholder Engagement Assessment Matrix: C = current engagement level; D = desired engagement level. Gap requires targeted engagement activities.\n• Stakeholder responsibility: Assign only ONE responsibility at a time — wait for prior deadline before adding another. Prevents overload and maintains accountability."),
                s("Communication Methods", tableHeaders = listOf("Method", "Direction", "Best For", "Examples"), tableRows = listOf(listOf("Interactive", "Two-way, real-time — MOST EFFECTIVE for understanding", "Conflict resolution, sensitive topics, complex negotiations, problem-solving", "Meetings, phone calls, video conferences"), listOf("Push", "One-way; sender distributes to recipients; no confirmation of understanding", "Status updates, routine information, announcements", "Email, reports, memos, press releases, newsletters"), listOf("Pull", "Recipients access on demand when they need it", "Large audiences, reference material, optional information", "Intranets, SharePoint, knowledge bases, portals"))),
                s("Communication Methods", "Communication Channels"),
                s("Communications Management Plan — Must Know Contents", "• Who needs what information, from whom, in what format, with what frequency\n• Methods and technology used for each type of communication and each stakeholder group\n• Frequency and timing schedules for regular communications\n• Escalation path and timeframes for unresolved issues\n• Glossary of common terminology to ensure shared understanding\n• Constraints affecting communications (confidentiality, legal, regulatory, cultural)\n• Communication flow diagrams showing who communicates with whom"),
                s("Communication Skills — PMBOK 8 Three Dimensions", tableHeaders = listOf("Dimension", "Skills", "PMBOK 8 Notable Addition"), tableRows = listOf(listOf("Oral", "Active listening, presentation, questioning, meeting facilitation, interaction", "Active listening is key — PM spends 90% of time communicating"), listOf("Visual", "Data visualisation, dashboards, nonverbal communication, body language", "Nonverbal cues often communicate more than words"), listOf("Electronic", "Professional writing, email, texting, chatting, collaborative tools", "AI prompting formally listed as an electronic communication skill in PMBOK 8"))),
                s("Handling Stakeholder Issues", tableHeaders = listOf("Situation", "Correct PM Action"), tableRows = listOf(listOf("Stakeholder raises concerns about a missed requirement", "Review the established acceptance criteria and guide them through it — do not dismiss"), listOf("Complaints about communication or status reports", "Re-evaluate the communications plan and stakeholder engagement plan"), listOf("Stakeholder wants more project progress detail", "Encourage attendance at sprint reviews or demos; adjust communications frequency/format"), listOf("External threats beyond PM authority", "Escalate to the project sponsor — this is when escalation is appropriate"), listOf("Stakeholder conflict over project priorities", "Facilitate a collaborative discussion; use Power/Interest grid to inform approach"))),
                s("Power/Interest Grid — Full Strategy", tableHeaders = listOf("Quadrant", "Power", "Interest", "Strategy", "Example"), tableRows = listOf(listOf("Manage Closely", "High", "High", "Engage fully; involve in decisions; frequent communication", "Sponsor, key customer"), listOf("Keep Satisfied", "High", "Low", "Meet their needs; do not overwhelm with detail; escalation path", "Executive not directly involved; regulator"), listOf("Keep Informed", "Low", "High", "Regular updates; leverage as advocates", "End users, team members"), listOf("Monitor", "Low", "Low", "Minimal effort; watch for changes in position", "Peripheral departments"))),
                s("Other Stakeholder Models", tableHeaders = listOf("Model", "Dimensions", "Use"), tableRows = listOf(listOf("Power/Influence Grid", "Power (authority) vs Influence (active involvement)", "When influence differs from formal power"), listOf("Impact/Influence Grid", "Impact (ability to change plans) vs Influence", "Assessing who can change project direction"), listOf("Salience Model", "Power, Urgency, Legitimacy (3 circles)", "Complex stakeholder environments; identifies \"definitive\" stakeholders (all 3)"), listOf("Stakeholder Cube", "3D combination of grids", "Very complex projects"), listOf("Direction of Influence", "Upward (senior), Downward (team), Outward (external), Sideward (peers)", "Understanding influence relationships"))),
                s("Communication Models", tableHeaders = listOf("Model", "Components", "Key Insight"), tableRows = listOf(listOf("Basic Sender-Receiver", "Encode → Transmit → Decode → Acknowledge → Feedback", "Noise can disrupt any step; feedback confirms understanding"), listOf("Interactive Model", "Adds acknowledgement and feedback loops", "Communication is bidirectional; ensure message received"), listOf("Cross-Cultural Model", "Sender and receiver have different frames of reference", "Cultural context affects encoding and decoding"))),
                s("Communication Models", "Exam point: The SENDER is responsible for clear encoding and confirming the message was understood. The RECEIVER is responsible for decoding and acknowledging. Both share responsibility for effective communication.", SectionKind.KEY),
                s("Communication Types", tableHeaders = listOf("Dimension", "Options"), tableRows = listOf(listOf("Formal vs Informal", "Formal: reports, briefings, contracts. Informal: emails, conversations, social media"), listOf("Internal vs External", "Internal: within project/org. External: customers, vendors, public, regulators"), listOf("Vertical vs Horizontal", "Vertical: up/down the hierarchy. Horizontal: with peers"), listOf("Official vs Unofficial", "Official: annual reports, regulatory filings. Unofficial: off-the-record"), listOf("Written vs Oral", "Written: permanent, precise. Oral: immediate, nuanced"), listOf("Verbal vs Nonverbal", "Verbal: words. Nonverbal: body language, tone (55% body language, 38% tone, 7% words per Mehrabian)"))),
                s("Meeting Management Best Practices", "• Set a clear agenda and distribute it in advance\n• Define the purpose: decision, information sharing, problem-solving, or status\n• Timebox the meeting; start and end on time\n• Assign a facilitator, note-taker, and timekeeper\n• Document decisions, action items (with owners and due dates), and follow-ups\n• Distribute meeting minutes promptly\n• Do not hold a meeting when an email would suffice\n• Agile: Daily Scrum is 15 min max; Sprint Review ≤4h; Retrospective ≤3h (for 4-week sprint)"),
                s("Stakeholder Engagement in Agile", tableHeaders = listOf("Practice", "Stakeholder Involvement"), tableRows = listOf(listOf("Product Owner", "Single voice of the customer; represents all stakeholders to the team"), listOf("Sprint Review", "Stakeholders see working increment; give direct feedback"), listOf("Backlog Refinement", "Stakeholders contribute to backlog items via PO"), listOf("Information Radiators", "Big visible charts (burndown, Kanban board) keep stakeholders informed without meetings"), listOf("Customer Collaboration", "Manifesto value: customer collaboration over contract negotiation"))),
            )
        ),
        Chapter(
            "procurement",
            "📄 Procurement Management (Resources + Governance)",
            "Contract Types — Risk Allocation",
            "Knowledge domains",
            listOf(
                s("Contract Types — Risk Allocation", "The more DEFINED the scope, the more you can push risk to the SELLER. The more UNCERTAIN the scope, the more risk the BUYER must carry.", SectionKind.KEY),
                s("Contract Types — Risk Allocation", tableHeaders = listOf("Contract Type", "Risk: Buyer", "Risk: Seller", "When to Use", "Key Feature"), tableRows = listOf(listOf("FFP (Firm Fixed Price)", "Low ✅", "High ❌", "Well-defined scope; stable requirements; seller expertise known", "Price is fixed regardless of seller's actual costs"), listOf("FPIF (Fixed Price Incentive Fee)", "Low-Medium", "Medium", "Defined scope; want to incentivise performance efficiency", "Seller shares savings/overruns up to a ceiling price"), listOf("FPEPA (Fixed Price Economic Price Adjustment)", "Low-Medium", "Medium", "Long-term contracts; economic fluctuations expected (inflation)", "Pre-defined price adjustment formulas for economic changes"), listOf("CPFF (Cost Plus Fixed Fee)", "High ❌", "Low ✅", "Uncertain scope; R&D; when seller expertise critical", "Seller reimbursed ALL costs + fixed fee regardless of outcome"), listOf("CPIF (Cost Plus Incentive Fee)", "High", "Low-Medium", "Long projects; want to incentivise cost efficiency", "Seller shares in savings below target cost"), listOf("CPAF (Cost Plus Award Fee)", "High", "Low", "Subjective performance criteria; hard to define deliverables", "Buyer evaluates performance and awards fee subjectively"), listOf("T&M (Time and Material)", "Medium", "Medium", "Unclear scope; staff augmentation; short-term work", "Hybrid: pay for time + materials used; buyer controls hours"))),
                s("Point of Total Assumption (PTA) — FPIF Contracts Only", "Point of Total Assumption"),
                s("Procurement Documents", tableHeaders = listOf("Document", "Used When", "Purpose"), tableRows = listOf(listOf("RFP (Request for Proposal)", "Complex requirements; need vendor solution approach", "Request technical approach + price + qualifications"), listOf("RFQ (Request for Quotation)", "Clear specifications; price is primary decision factor", "Request price quotes for defined products/services"), listOf("IFB (Invitation for Bid)", "Well-defined scope; selecting on price only", "Formal bid process; lowest compliant bid wins"), listOf("SOW (Statement of Work)", "Part of contract package", "Describes what the seller must deliver in detail"))),
                s("Vendor Management Best Practices", "• Always review the Procurement Management Plan and contract/agreement FIRST before taking action\n• Communicate face-to-face or by phone to resolve vendor issues — do not rely solely on email\n• Evaluate alternatives before considering contract cancellation\n• Vendor delivery delays or quality issues → meet with vendor AND team to brainstorm solutions\n• In the event of a formal claim → escalate to Claims Administration — do not try to resolve legally yourself\n• Conduct regular milestone status reviews and walkthroughs to ensure contractor is on track\n• Make-or-buy analysis: gather data on requirements → analyse internal vs external options → formal decision"),
                s("Make-or-Buy Analysis", "• Make: Build internally — use when: unique capability needed, confidentiality required, idle capacity exists, lower long-term cost\n• Buy: Outsource/procure — use when: specialised expertise needed, faster delivery required, lower risk, not core competency\n• Analysis should consider: total cost, risk, quality, capacity, strategic fit, and delivery timeline\n• PMBOK 8: Make-or-buy analysis explicitly listed as a tool in both Resources and Governance domains"),
                s("Procurement Process Flow", "Plan Procurement\n\nPrepare Bid Documents\n\nSolicit Sellers\n\nEvaluate Proposals\n\nSelect Seller\n\nAward Contract\n\nAdminister Contract\n\nClose Procurement"),
                s("Seller Selection Criteria", tableHeaders = listOf("Criterion", "Description"), tableRows = listOf(listOf("Technical Capability", "Does the seller have the skills and technology?"), listOf("Management Approach", "How will they manage the work?"), listOf("Financial Capacity", "Can they afford to deliver? Are they financially stable?"), listOf("Past Performance", "References, track record, similar projects"), listOf("Price / Total Cost", "Not just bid price — total cost of ownership"), listOf("Risk", "Seller-specific risks (single source, geopolitical, IP)"), listOf("Sustainability", "PMBOK 8: seller's environmental and social practices"))),
                s("Bidder Conferences", "• Meeting with ALL prospective sellers BEFORE bid submission\n• Purpose: ensure all sellers have a common, clear understanding of requirements\n• All questions and answers shared with ALL bidders — no private information\n• Ensures fairness (PMI Code of Ethics — Fairness value)\n• Also called: contractor conferences, vendor conferences, pre-bid conferences"),
                s("Contract Elements — What Makes a Valid Contract", tableHeaders = listOf("Element", "Description"), tableRows = listOf(listOf("Offer", "One party proposes terms"), listOf("Acceptance", "Other party agrees to those terms"), listOf("Consideration", "Something of value exchanged (money, services)"), listOf("Legal Capacity", "Both parties legally able to enter contract"), listOf("Legal Purpose", "Contract must be for a lawful purpose"))),
                s("Contract Change Control", "• All contract changes go through the CONTRACT change control system (defined in the contract)\n• Contract changes are more formal than internal project changes — legally binding\n• Constructive change: when the buyer directs work not in the contract without formal change → seller can claim\n• Claims: disagreements about compensation or terms → resolve through Claims Administration → mediation → arbitration → litigation\n• PM should aim to resolve claims through negotiation first (collaborative approach)"),
                s("Procurement in Agile", tableHeaders = listOf("Aspect", "Agile Approach"), tableRows = listOf(listOf("Contract Type", "T&M or cost-reimbursable preferred — scope evolves"), listOf("Master Agreement", "Master Services Agreement (MSA) + statement of work per sprint or release"), listOf("Scope Flexibility", "Fixed price per sprint with variable scope; or \"not-to-exceed\" with early termination option"), listOf("Collaboration", "Vendor team members may work as part of the Scrum team"), listOf("Incremental Delivery", "Payment tied to delivered increments, not milestones"))),
            )
        ),
        Chapter(
            "leadership",
            "👩‍💼 Leadership, Teams & Motivation",
            "Leadership Styles",
            "People domain",
            listOf(
                s("Leadership Styles", tableHeaders = listOf("Style", "Description", "When to Use", "PMI View"), tableRows = listOf(listOf("Servant Leadership", "PM SERVES the team; removes impediments; puts team needs first; enables success", "Agile contexts; high-performing teams; empowered cultures", "✅ PMI's preferred style — especially for agile"), listOf("Transformational", "Inspires through vision, purpose, and passion for change; challenges status quo", "Change initiatives; motivating teams through difficulty", "✅ Effective for driving innovation"), listOf("Situational", "Adapts leadership style to team maturity level and task complexity", "Most practical — applies across all project types", "✅ Flexible and context-appropriate"), listOf("Transactional", "Rewards for performance; penalties for non-performance; exchange-based", "Routine, well-defined, structured work", "Moderate — can limit creativity"), listOf("Laissez-faire", "Hands-off; minimal direction; team fully autonomous", "Expert teams; research; high-trust contexts", "Use with caution — can mean abdication"), listOf("Democratic/Participative", "Involves team in decisions; builds consensus; collaborative", "Complex decisions requiring broad input and buy-in", "Good for major decisions and change"), listOf("Autocratic/Directive", "PM decides alone; immediate compliance expected", "True emergencies; inexperienced teams needing direction; safety situations", "Only appropriate in genuine crises"))),
                s("Leadership Styles", "PMBOK 8: Leadership is SHARED — any team member, stakeholder, or professional can demonstrate leadership behaviours at any point. Leadership ≠ authority. Authority = position. Leadership = inspiring others.", SectionKind.KEY),
                s("Team Development — Tuckman's Model", "Performing\n\nAdjourning"),
                s("Team Development — Tuckman's Model", tableHeaders = listOf("Stage", "Team Behaviour", "PM Action"), tableRows = listOf(listOf("Forming", "Polite; cautious; dependent on leader; unclear roles and expectations", "Define roles clearly; set expectations; build relationships; orient the team"), listOf("Storming", "Conflict; power struggles; frustration; differing opinions on approach", "Facilitate conflict resolution; maintain focus on goals; coach through tension"), listOf("Norming", "Team establishes norms; cooperation improves; trust builds; roles clarified", "Reinforce positive behaviours; empower team; begin stepping back as leader"), listOf("Performing", "High performance; self-organising; minimal supervision needed; interdependent", "Delegate; support; celebrate successes; remove obstacles as they arise"), listOf("Adjourning", "Project ends; team disbands; mixed emotions (pride, sadness, uncertainty)", "Recognise contributions; celebrate achievements; capture lessons learned"))),
                s("Team Development — Tuckman's Model", "Teams can move BACKWARDS through stages when team composition changes, major conflict occurs, or a challenging new phase begins. This is normal and expected. Storming may recur.", SectionKind.TIP),
                s("Motivation Theories — Detailed", tableHeaders = listOf("Theory", "Key Concept", "What It Means for a PM"), tableRows = listOf(listOf("Maslow's Hierarchy of Needs", "Five levels: Physiological → Safety → Social → Esteem → Self-Actualisation. Lower needs must be met before higher ones motivate.", "If basic needs (pay, safety, job security) aren't met, recognition and growth won't motivate. Address the level they are actually at."), listOf("Herzberg's Two-Factor Theory", "Hygiene Factors (pay, conditions, security) PREVENT dissatisfaction but do NOT create motivation. Motivators (achievement, recognition, meaningful work, responsibility, growth) create TRUE satisfaction and motivation.", "Pay alone won't motivate your team — they also need recognition, challenging work, and growth opportunities. Hygiene factors are a floor, not a ceiling."), listOf("McGregor Theory X", "People inherently dislike work; must be controlled, directed, and threatened to perform.", "Leads to authoritarian, micromanaging style. PMI does NOT endorse this."), listOf("McGregor Theory Y", "People are self-motivated; find work natural; seek responsibility; are creative when given the chance.", "PMI's preferred view — servant leadership and empowered culture align with Theory Y."), listOf("McClelland's Achievement Theory", "Three primary needs: Achievement (mastery, accomplishing goals), Affiliation (belonging, relationships), Power (influence, leading others).", "Match team member roles to their dominant need. Achievement-oriented → challenging goals. Affiliation → collaborative roles. Power → leadership opportunities."), listOf("Expectancy Theory (Vroom)", "Motivation = Expectancy (effort leads to performance) × Instrumentality (performance leads to reward) × Valence (reward is valued).", "All three must be present. If team doesn't believe effort leads to success, or success won't be rewarded, or the reward isn't valued — motivation drops."))),
                s("Motivation Theories — Detailed", "Herzberg is THE most tested motivation theory. Hygiene factors prevent DIS-satisfaction (two different scales — not two ends of one scale). Salary preventing unhappiness ≠ salary creating happiness.", SectionKind.DANGER),
                s("Power Types", tableHeaders = listOf("Power Type", "Source", "PMI Preference", "Why?"), tableRows = listOf(listOf("Expert", "Knowledge, skill, and experience in a relevant domain", "✅ Highest — most sustainable", "Respected regardless of title; does not depend on position; builds credibility"), listOf("Referent", "Personal charisma, trust built over time, quality relationships", "✅ High — builds loyalty", "Creates genuine followership; earned through consistent trustworthy behaviour"), listOf("Reward", "Ability to give incentives, recognition, resources, promotions", "Moderate — use carefully", "Effective but can create dependency on external rewards; may breed entitlement"), listOf("Legitimate / Formal", "Title or position in the organisational hierarchy", "Moderate — limited effectiveness", "Authority without influence is fragile; people comply but may not commit"), listOf("Penalty / Coercive", "Ability to punish, withhold, or threaten consequences", "❌ Lowest — avoid", "Damages trust, creates resentment, kills psychological safety and creativity"))),
                s("Virtual / Distributed Teams", "• Accommodate different time zones and cultural differences in all communications\n• Use video conferencing for important discussions — see faces, build relationships\n• Establish clear communication norms and response time expectations\n• Co-location is always preferred when feasible — face-to-face builds trust fastest\n• Cultural intelligence: respect language barriers, different communication styles, varied norms\n• Scrum: Daily Scrum should be scheduled for a time that works for all time zones"),
                s("Situational Leadership — Hersey & Blanchard", "The leader adapts their style based on the follower's competence and commitment:"),
                s("Situational Leadership — Hersey & Blanchard", tableHeaders = listOf("Style", "Directive", "Supportive", "When Team Is...", "Leader Does..."), tableRows = listOf(listOf("S1 — Directing/Telling", "High", "Low", "Low competence, high commitment (enthusiastic beginner)", "Gives specific instructions; supervises closely"), listOf("S2 — Coaching/Selling", "High", "High", "Some competence, low commitment (disillusioned learner)", "Explains decisions; solicits input; encourages"), listOf("S3 — Supporting/Participating", "Low", "High", "High competence, variable commitment (capable but cautious)", "Shares decision-making; facilitates"), listOf("S4 — Delegating", "Low", "Low", "High competence, high commitment (self-reliant achiever)", "Hands over responsibility; monitors lightly"))),
                s("Situational Leadership — Hersey & Blanchard", "Exam point: Match the style to the person and task — not one style for the whole team. A senior engineer may need S4 on familiar work but S2 on a new technology.", SectionKind.TIP),
                s("Team Charter", "The Team Charter (also called Team Agreement or Working Agreement) documents team values, agreements, and operating guidelines. Created BY the team, not FOR the team."),
                s("Team Charter", tableHeaders = listOf("Section", "Content"), tableRows = listOf(listOf("Team Values", "What the team believes in — respect, transparency, quality"), listOf("Communication Guidelines", "Preferred channels, response time expectations, meeting norms"), listOf("Decision-Making Criteria", "How decisions are made — consensus, majority, PO decides"), listOf("Conflict Resolution Process", "How the team handles disagreements"), listOf("Meeting Guidelines", "Attendance, punctuality, agenda, facilitation"), listOf("Ground Rules", "Working hours, core hours for virtual teams, tool usage"))),
                s("Team Charter", "When a question involves team norms, working agreements, or \"how the team operates\" — the answer often involves referencing or updating the Team Charter.", SectionKind.KEY),
                s("Recognition and Rewards", "• Rewards should be based on agreed criteria in the resource management plan\n• Only reward desirable behaviour — rewarding overtime encourages overtime culture\n• Consider cultural differences — public recognition is valued in some cultures, embarrassing in others\n• Intrinsic rewards (autonomy, mastery, purpose) are often more powerful than extrinsic (money)\n• Recognise the TEAM as well as individuals — avoid creating internal competition\n• Timeliness matters — recognise promptly, not months later"),
                s("Team Building Activities", tableHeaders = listOf("Stage", "Activity Type"), tableRows = listOf(listOf("Kick-off", "Introductions, charter development, vision sharing"), listOf("Ongoing", "Regular check-ins, celebrating milestones, social events"), listOf("Virtual teams", "Video introductions, virtual coffee breaks, shared online spaces"), listOf("Conflict phase", "Facilitated workshops, structured problem-solving sessions"), listOf("Closure", "Retrospective, celebration, recognition of contributions"))),
                s("Coaching vs. Mentoring vs. Training", tableHeaders = listOf("Method", "Focus", "Duration", "Who Leads"), tableRows = listOf(listOf("Training", "Specific skill acquisition", "Short; structured", "Trainer/instructor"), listOf("Coaching", "Performance improvement through questions and guidance", "Medium; goal-focused", "Coach (asks, does not tell)"), listOf("Mentoring", "Career development; sharing experience and wisdom", "Long-term; relationship-based", "Mentor (shares experience)"))),
                s("Decision-Making Techniques", tableHeaders = listOf("Technique", "Description", "When to Use"), tableRows = listOf(listOf("Unanimity", "Everyone agrees", "Small groups; critical decisions"), listOf("Majority", "More than 50% agree", "Larger groups; time constraints"), listOf("Plurality", "Largest block decides (even if <50%)", "Multiple options; no clear majority"), listOf("Autocratic", "One person decides", "Emergencies; clear authority"), listOf("Consensus", "Everyone can live with the decision (not necessarily first choice)", "Agile teams; buy-in critical"), listOf("Fist of Five", "Vote with fingers (5 = fully support, 1 = strongly oppose)", "Quick agile consensus check"), listOf("Dot Voting", "Each person places dots on preferred options", "Prioritising many options quickly"))),
            )
        ),
        Chapter(
            "people-advanced",
            "🧩 Advanced People Skills — Servant Leadership, TKI & Psychological Safety",
            "Servant Leadership — Advanced Practice",
            "People domain",
            listOf(
                s("Key", "People is 33% of the exam — roughly 59 questions. Almost none are definitional; they are scenarios testing judgment. This section gives you the frameworks behind the judgment.", SectionKind.KEY),
                s("Servant Leadership — Advanced Practice", "Servant leadership is PMI's preferred model. Greenleaf's original test: \"Do those served grow as persons? Do they become healthier, wiser, freer, more autonomous, more likely themselves to become servants?\""),
                s("Servant Leadership — Advanced Practice", tableHeaders = listOf("Characteristic", "What the Servant Leader Does", "Anti-Pattern"), tableRows = listOf(listOf("Listening", "Seeks to hear and understand before responding; listens to what is unsaid", "Waits for their turn to talk; interrupts"), listOf("Empathy", "Assumes good intent; understands others' perspectives and constraints", "Judges; assumes laziness or incompetence"), listOf("Healing", "Helps team members recover from setbacks, conflict, and failure", "Assigns blame; \"moves on\" without addressing damage"), listOf("Awareness", "Self-aware and situationally aware; understands ethics, power, values", "Oblivious to team mood, politics, or own impact"), listOf("Persuasion", "Convinces rather than coerces; builds consensus", "Uses positional authority: \"because I said so\""), listOf("Conceptualisation", "Thinks beyond day-to-day; nurtures vision", "Purely tactical; no sense of purpose"), listOf("Foresight", "Learns from the past; understands the present; anticipates consequences", "Reactive; surprised by predictable events"), listOf("Stewardship", "Holds the team, organisation, and resources in trust for others", "Treats the team as a means to personal advancement"), listOf("Commitment to growth", "Invests in every person's development", "Only develops \"high potentials\"; neglects others"), listOf("Building community", "Creates belonging and shared identity", "Pits people against each other; tolerates cliques"))),
                s("Servant Leader Behaviours in Agile Contexts", tableHeaders = listOf("Situation", "Servant Leader Response"), tableRows = listOf(listOf("Team blocked by another department", "Personally removes the impediment; does not delegate the escalation back to the team"), listOf("Team makes a technical decision the PM disagrees with", "Voices concern once, then supports the team's decision (unless safety/ethics)"), listOf("Stakeholder interrupts developers mid-sprint", "Shields the team; redirects the stakeholder to the PO / next sprint review"), listOf("Team member struggling", "Coaches privately; asks what support they need; never exposes them publicly"), listOf("Team succeeds", "Credits the team publicly; takes no personal credit"), listOf("Team fails", "Takes accountability publicly; analyses privately with the team without blame"), listOf("Team wants to try a new practice", "Enables the experiment; helps measure results; supports even if it fails"))),
                s("Thomas-Kilmann Conflict Mode Instrument (TKI)", "TKI maps five conflict modes on two axes: Assertiveness (concern for own goals) and Cooperativeness (concern for others' goals). Every mode has a place — the skill is choosing the right one."),
                s("Thomas-Kilmann Conflict Mode Instrument (TKI)", tableHeaders = listOf("Mode", "Assertive?", "Cooperative?", "Description", "Use When", "Avoid When"), tableRows = listOf(listOf("Competing (Forcing)", "High", "Low", "Win-lose; pursue own goals at others' expense", "Emergency; safety; unpopular but necessary decision; protecting against exploitation", "Relationship matters; you may be wrong; long-term collaboration needed"), listOf("Collaborating", "High", "High", "Win-win; work together to find a solution satisfying everyone", "Both sets of concerns are important; need buy-in; merge insights; build relationship", "Time-critical; issue trivial; other party acting in bad faith"), listOf("Compromising", "Medium", "Medium", "Split the difference; each side gives something", "Goals moderately important; equal power; temporary settlement; time pressure", "Would sacrifice a critical principle; a better solution exists via collaboration"), listOf("Avoiding", "Low", "Low", "Sidestep; postpone; withdraw", "Issue trivial; no chance of winning; cooling-off needed; others can resolve better", "Issue is important; decision needed now; avoidance breeds resentment"), listOf("Accommodating", "Low", "High", "Yield; satisfy others' concerns at expense of own", "You are wrong; issue matters more to them; preserve harmony; build goodwill for later", "Issue is important to you; sets a precedent of being exploited"))),
                s("Thomas-Kilmann Conflict Mode Instrument (TKI)", "PMI's default: Collaborating is preferred; Avoiding is least preferred. But the exam tests SITUATIONAL judgment — in a genuine safety emergency, Competing is correct. In a trivial dispute where tempers are high, Avoiding (temporarily) may be correct.", SectionKind.WARN),
                s("TKI vs. PMBOK Conflict Techniques — Mapping", tableHeaders = listOf("TKI Mode", "PMBOK Term", "Same Thing?"), tableRows = listOf(listOf("Collaborating", "Collaborate / Problem Solve", "Yes"), listOf("Compromising", "Compromise / Reconcile", "Yes"), listOf("Accommodating", "Smooth / Accommodate", "Yes"), listOf("Competing", "Force / Direct", "Yes"), listOf("Avoiding", "Withdraw / Avoid", "Yes"))),
                s("Sources of Conflict on Projects (in order of frequency)", "• Schedules — the #1 source; conflicting priorities and deadlines\n• Project priorities — disagreement over what matters most\n• Resources — competition for people, equipment, budget\n• Technical opinions — disagreement over approach\n• Administrative procedures — how things get done\n• Cost — budget disputes\n• Personalities — the LEAST frequent source, despite popular belief"),
                s("Sources of Conflict on Projects (in order of frequency)", "Exam trap: personality clashes are the LEAST common cause of project conflict. Schedules are the MOST common. If a question asks \"what is the most likely source of this conflict?\" — think schedule, not personality.", SectionKind.TIP),
                s("Psychological Safety — Amy Edmondson's Framework", "Psychological safety is the shared belief that the team is safe for interpersonal risk-taking — speaking up, asking questions, admitting mistakes, and disagreeing without fear of punishment or humiliation. Google's Project Aristotle found it the #1 predictor of team effectiveness."),
                s("Psychological Safety — Amy Edmondson's Framework", tableHeaders = listOf("Level", "Description", "Signs"), tableRows = listOf(listOf("1. Inclusion Safety", "I feel accepted as a member of the team", "People are greeted, included in conversations, not ignored"), listOf("2. Learner Safety", "I can ask questions, experiment, and make mistakes", "People ask \"dumb\" questions; mistakes discussed openly"), listOf("3. Contributor Safety", "I can contribute ideas and use my skills", "People volunteer ideas; quiet members speak in meetings"), listOf("4. Challenger Safety", "I can challenge the status quo and disagree with leaders", "People say \"I think we are wrong about this\" to the PM"))),
                s("How the PM Builds Psychological Safety", tableHeaders = listOf("Practice", "Example"), tableRows = listOf(listOf("Frame work as learning", "\"This is complex — we will make mistakes, and that is how we learn\""), listOf("Acknowledge own fallibility", "\"I may have missed something here — what do you see?\""), listOf("Model curiosity", "Ask questions; ask for dissent: \"Who sees this differently?\""), listOf("Respond productively to bad news", "Thank the messenger; focus on the problem, not the person"), listOf("Blameless post-mortems", "Analyse failures for system causes, not individual fault"), listOf("Protect dissenters", "Publicly value the person who raised the concern, even if it turns out unfounded"), listOf("Consistent boundaries", "Safety is not permissiveness — unethical or abusive behaviour is still addressed"))),
                s("Signs Psychological Safety Is LOW", "• Meetings are silent; only the PM and one or two seniors speak\n• Problems surface late — people hide bad news until it is undeniable\n• Status is always \"green\" until suddenly \"red\"\n• Mistakes are hidden or blamed on others\n• No one challenges obviously flawed plans\n• High turnover; disengagement; \"quiet quitting\""),
                s("Signs Psychological Safety Is LOW", "The team that misreported status to hide delays (from the Mindset quiz) is a psychological safety failure. The PM's job is not only to fix the report but to fix the environment that made people afraid to report honestly.", SectionKind.KEY),
                s("Emotional Intelligence — Applied Techniques", tableHeaders = listOf("Technique", "How", "When"), tableRows = listOf(listOf("Active Listening", "Full attention; paraphrase; reflect feelings; ask clarifying questions; do not interrupt", "Every stakeholder conversation; especially conflict"), listOf("Naming the emotion", "\"It sounds like you are frustrated that the timeline moved again\"", "De-escalation; showing empathy"), listOf("The pause", "Take a breath before responding to provocation", "When you feel a strong reaction"), listOf("Perspective-taking", "\"If I were in their role, what would I be worried about?\"", "Before negotiating or delivering bad news"), listOf("Non-violent communication (NVC)", "Observation → Feeling → Need → Request. \"When the report was late (observation), I felt concerned (feeling) because the sponsor needs it for the board (need). Could you let me know earlier next time if it will slip? (request)\"", "Giving feedback without blame"), listOf("Reading the room", "Notice body language, silence, side conversations, energy level", "Meetings; retrospectives"), listOf("Regulating others", "Calm tone, slower pace, acknowledge, redirect to problem-solving", "Heated meetings"))),
                s("Influencing Without Authority", "Most PMs (especially in matrix organisations) have responsibility without authority. Influence techniques:"),
                s("Influencing Without Authority", tableHeaders = listOf("Technique", "Description"), tableRows = listOf(listOf("Reciprocity", "Help others first; build a bank of goodwill"), listOf("Social proof", "\"Three other teams have adopted this and seen results\""), listOf("Expert power", "Demonstrate competence; be the person people ask"), listOf("Framing in their interest", "Explain how the request helps THEIR goals"), listOf("Coalition building", "Align supporters before the meeting; avoid ambushes"), listOf("Consistency", "Small commitments lead to larger ones"), listOf("Transparency", "Share data and reasoning; invite challenge"))),
                s("Motivating Knowledge Workers — Daniel Pink's Model", tableHeaders = listOf("Driver", "Definition", "PM Application"), tableRows = listOf(listOf("Autonomy", "Desire to direct our own lives and work", "Let the team decide HOW; define WHAT and WHY"), listOf("Mastery", "Urge to get better at something that matters", "Provide challenging work; learning time; feedback"), listOf("Purpose", "Yearning to contribute to something larger than ourselves", "Connect work to outcomes and impact; share the vision"))),
                s("Motivating Knowledge Workers — Daniel Pink's Model", "Pink's research: for complex, creative work, carrot-and-stick rewards (bonuses, penalties) can REDUCE performance. Autonomy, mastery, and purpose drive knowledge workers — aligning with Herzberg's motivators and McGregor's Theory Y.", SectionKind.TIP),
            )
        ),
        Chapter(
            "ethics",
            "⚖️ PMI Code of Ethics & Professional Conduct",
            "The Four Values — Aspirational and Mandatory Standards",
            "People domain",
            listOf(
                s("Danger", "Ethics is not a separate exam domain — it is woven through ALL three domains, especially People (33%) and Business Environment (26%). Situational questions constantly test whether you will choose integrity over convenience.", SectionKind.DANGER),
                s("The Four Values — Aspirational and Mandatory Standards", "Each value has aspirational standards (what we strive for) and mandatory standards (firm requirements — violations can result in disciplinary action by PMI)."),
                s("1. Responsibility", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Make decisions based on the best interests of society, public safety, and the environment", "Inform ourselves of and uphold policies, rules, regulations, and laws governing our work"), listOf("Accept only assignments consistent with our background, experience, skills, and qualifications", "Report unethical or illegal conduct to appropriate management and, if necessary, to those affected"), listOf("Fulfil commitments we undertake — we do what we say we will do", "Bring violations of the Code to PMI's attention; only file complaints substantiated by facts"), listOf("Take ownership of errors and make corrections promptly", "Pursue disciplinary action against anyone who retaliates against a person raising ethics concerns"))),
                s("2. Respect", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Inform ourselves about norms and customs of others; avoid behaviour they may consider disrespectful", "Negotiate in good faith"), listOf("Listen to others' points of view; seek to understand them", "Do not exercise power of expertise or position to influence decisions for personal benefit at others' expense"), listOf("Approach directly those with whom we have a conflict or disagreement", "Do not act in an abusive manner toward others"), listOf("Conduct ourselves professionally, even when it is not reciprocated", "Respect the property rights of others"))),
                s("3. Fairness", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Demonstrate transparency in our decision-making process", "Proactively and fully disclose any real or potential conflicts of interest"), listOf("Constantly re-examine impartiality and objectivity; take corrective action as appropriate", "When a conflict of interest exists, refrain from participating in decisions until fully disclosed and stakeholders consent to proceed"), listOf("Provide equal access to information to those authorised to have it", "Do not hire, fire, reward, or punish based on personal considerations (favouritism, nepotism, bribery)"), listOf("Make opportunities equally available to qualified candidates", "Do not discriminate on gender, race, age, religion, disability, nationality, or sexual orientation"))),
                s("4. Honesty", tableHeaders = listOf("Aspirational", "Mandatory"), tableRows = listOf(listOf("Earnestly seek to understand the truth", "Do not engage in or condone behaviour designed to deceive others — false statements, half-truths, information out of context, withholding information"), listOf("Be truthful in our communications and conduct", "Do not engage in dishonest behaviour with the intention of personal gain or at the expense of another"), listOf("Provide accurate information in a timely manner", "—"), listOf("Make commitments and promises in good faith", "—"), listOf("Create an environment where others feel safe to tell the truth", "—"))),
                s("4. Honesty", "Memory hook: R-R-F-H → \"Really Respect Fair Honesty.\" Responsibility · Respect · Fairness · Honesty.", SectionKind.TIP),
                s("Ethical Decision-Making Framework (PMI EDMF)", "PMI publishes a five-step Ethical Decision-Making Framework. When a question describes an ethical dilemma, walk through these steps:\n\n1. Assessment\n\n2. Alternatives\n\n3. Analysis\n\n4. Application\n\n5. Action"),
                s("Ethical Decision-Making Framework (PMI EDMF)", tableHeaders = listOf("Step", "What You Do", "Key Questions"), tableRows = listOf(listOf("1. Assessment", "Ensure you have all the facts about the ethical dilemma", "What are the facts? Is it legal? Does it violate the Code? Who is affected?"), listOf("2. Alternatives", "Consider your choices — including the option of doing nothing", "What are ALL the options? What are the consequences of each?"), listOf("3. Analysis", "Identify the candidate decision and test its validity", "Does it uphold all four values? Would I be comfortable if it were public? Does it treat everyone fairly?"), listOf("4. Application", "Apply ethical principles to the candidate decision", "Is it consistent with PMI values? Organisational values? Cultural context (without compromising the Code)?"), listOf("5. Action", "Make the decision and take responsibility for it", "Document the decision. Communicate to affected parties. Own the outcome."))),
                s("Conflict of Interest — Detailed", tableHeaders = listOf("Situation", "Is It a Conflict?", "Correct Action"), tableRows = listOf(listOf("Your brother-in-law's company is bidding on your project", "Yes — personal relationship with a bidder", "Disclose immediately in writing; recuse from evaluation and selection"), listOf("You own shares in a vendor being considered", "Yes — financial interest", "Disclose; recuse from decision; consider divesting if material"), listOf("A vendor offers you a paid speaking engagement during evaluation", "Yes — potential inducement", "Decline until procurement is complete; disclose the offer"), listOf("Your previous employer is a bidder", "Potential — perceived bias", "Disclose; let stakeholders decide whether you should participate"), listOf("You are asked to evaluate a proposal from a company where you interviewed last year", "Potential — perceived interest", "Disclose; typically fine to proceed if stakeholders consent"), listOf("A team member reports to you AND is your close friend", "Potential — favouritism risk", "Disclose to your manager; ensure evaluations are objective and documented"))),
                s("Conflict of Interest — Detailed", "The test is not just ACTUAL conflict — it is also PERCEIVED conflict. If a reasonable observer might think your judgment is compromised, disclose it. When in doubt, disclose.", SectionKind.KEY),
                s("Professional Responsibility Scenarios — Full Reference", tableHeaders = listOf("Scenario", "Wrong Response", "Right Response"), tableRows = listOf(listOf("Sponsor tells you to report \"green\" status when project is \"red\"", "Comply to keep the sponsor happy", "Refuse; report accurately; explain that misreporting harms decision-making and violates Honesty"), listOf("You discover a colleague falsifying safety test results", "Confront them privately and let it go if they promise to stop", "Report through appropriate channels — public safety is at stake (Responsibility)"), listOf("A team member from another culture greets you in a way you find odd", "Correct their behaviour", "Inform yourself about their norms; adapt (Respect)"), listOf("You are offered a project you are not qualified for", "Accept — it is a great career move", "Decline or seek support/training first (Responsibility — accept only qualified assignments)"), listOf("Local custom requires \"facilitation payments\" to get permits", "Pay — \"when in Rome\"", "Do not pay bribes regardless of local custom (Fairness/Honesty; also usually illegal under FCPA/UK Bribery Act)"), listOf("A stakeholder asks you to share confidential bid information with a preferred vendor", "Share — the stakeholder has authority", "Refuse — equal access to information (Fairness)"), listOf("You made an estimation error costing the project \$50K", "Blame the data you were given", "Own the error; propose recovery plan (Responsibility)"), listOf("A team member is being bullied by another", "Stay out of it — not your business", "Intervene; address the abusive behaviour (Respect — mandatory standard)"), listOf("You learn of a PMI Code violation by another PMP", "Ignore — not your role to police", "Report to PMI if substantiated by facts (Responsibility — mandatory)"), listOf("A contractor offers a small gift at project completion", "Accept — the project is done", "Check organisational policy; modest gifts after completion are often acceptable, but disclose"))),
                s("Ethics in the Age of AI (2026)", "• Transparency: Disclose when AI has been used to generate project artifacts, estimates, or reports\n• Accountability: The PM remains accountable for AI-generated outputs — \"the AI did it\" is never a defence\n• Bias: AI models can encode bias; PMs must check AI recommendations for fairness (e.g., in resource allocation, vendor selection)\n• Data privacy: Do not feed confidential project or personal data into external AI tools without authorisation\n• Honesty: Do not present AI-generated content as human expert judgment\n• Intellectual property: Respect IP rights in AI training data and outputs"),
            )
        ),
        Chapter(
            "business",
            "🏢 Business Environment (8% of Exam)",
            "Portfolio, Programs, and Projects — Hierarchy",
            "Business & tailoring",
            listOf(
                s("Note", "26% of the exam in 2026 ECO — Business Environment tripled from 8% to 26%. These questions now carry significant weight and cover governance, compliance, AI, sustainability, and strategy. Do NOT treat as minor. and conceptual. Do not ignore them — they are usually straightforward if you know the theory.", SectionKind.NOTE),
                s("Portfolio, Programs, and Projects — Hierarchy", tableHeaders = listOf("Level", "Definition", "Managed By", "Success Measured By"), tableRows = listOf(listOf("Portfolio", "Projects, programs, subsidiary portfolios, and operations managed as a group to achieve STRATEGIC objectives", "Portfolio Manager / Executive", "Strategic alignment; maximised return on investment; right mix of initiatives"), listOf("Program", "Related projects managed in a coordinated manner to obtain BENEFITS not available from managing them individually", "Program Manager", "Benefits realisation beyond individual projects; synergies achieved"), listOf("Project", "Temporary endeavour to create a unique product, service, or result with a definitive beginning and end", "Project Manager", "On time, on budget, scope met, quality achieved, value delivered"), listOf("Operations", "Ongoing, repetitive activities that produce the same result repeatedly", "Operations Manager", "Efficiency, productivity, continuous quality improvement"))),
                s("Organisational Structures — PM Authority Levels", tableHeaders = listOf("Structure", "PM Authority", "PM Time Commitment", "Resource Availability", "Who Controls Resources?"), tableRows = listOf(listOf("Organic / Simple", "Little or none", "Part-time", "Little or none", "Owner or Operator"), listOf("Functional", "Little or none", "Part-time", "Little or none", "Functional Manager — PM has no authority"), listOf("Matrix — Weak", "Low", "Part-time", "Low", "Functional Manager dominant"), listOf("Matrix — Balanced", "Low to Moderate", "Part-time", "Low to Moderate", "Shared between PM and Functional Manager"), listOf("Matrix — Strong", "Moderate to High", "Full-time", "Moderate to High", "PM dominant"), listOf("Project-Oriented (Projectised)", "High to Almost Total", "Full-time", "High to Almost Total", "Project Manager controls"), listOf("PMO Structure", "High to Almost Total", "Full-time", "High", "PMO / Project Manager"))),
                s("Organisational Structures — PM Authority Levels", "The more PROJECT-ORIENTED the structure, the MORE authority the PM has. In a functional org, the PM has almost no authority — everything goes through the Functional Manager. This creates the classic \"PM with responsibility but no authority\" challenge.", SectionKind.WARN),
                s("PMO Types — Know All Three", tableHeaders = listOf("PMO Type", "Control Level", "Role", "Exam Tip"), tableRows = listOf(listOf("Supportive", "Low — consultative", "Repository of templates, best practices, training, lessons learned. Projects can use or ignore.", "PM has the most autonomy here"), listOf("Controlling", "Moderate — compliance required", "Requires adoption of frameworks, templates, governance tools, and reporting. Projects must comply.", "PM must follow PMO standards"), listOf("Directive", "High — directly manages", "PMO members ARE the project managers — they take direct control of projects.", "PM works FOR the PMO"))),
                s("EEF vs. OPA — Critical Distinction", "Enterprise Environmental Factors (EEF)\n Conditions NOT under the project team's control that influence, constrain, or direct the project. Can be INTERNAL or EXTERNAL.\n • Organisational culture and structure\n• Government or industry regulations and standards\n• Market conditions and competitive landscape\n• Infrastructure: physical environment, tools, IT systems\n• Commercial databases (published benchmarks, pricing)\n• Geographic distribution of facilities and resources"),
                s("Organisational Process Assets (OPA)", "Plans, processes, policies, procedures, and knowledge bases specific to the organisation. The project team can USE and UPDATE these.\n\n• Templates, forms, and standardised processes\n• Lessons learned repository from past projects\n• Historical project information and performance data\n• Change control procedures and CCB charter\n• Financial controls and reporting requirements\n• Project management information systems (PMIS)"),
                s("Organisational Process Assets (OPA)", "EEF = the environment you work IN (external constraints you cannot control). OPA = the organisational KNOWLEDGE you can work WITH (internal assets you can use and update). Both are inputs to most planning processes.", SectionKind.TIP),
                s("Benefits Management Plan — Contents", "• Target benefits: Tangible (revenue increase, cost savings) AND intangible (brand reputation, employee satisfaction)\n• Strategic alignment: How the benefits connect to organisational strategy and objectives\n• Timeframe: When benefits will be realised — short-term, long-term, ongoing, or by phase\n• Benefits owner: Who is accountable for monitoring, recording, and reporting benefits realisation\n• Metrics: Direct and indirect measures used to confirm benefits are being realised\n• Assumptions and risks: Factors expected to be in place for benefits to occur, and risks to realisation"),
                s("Governance and Project Governance", "• Organisational governance: Framework, functions, processes that guide strategy and operations at the enterprise level\n• Project governance: Framework for decisions, oversight, and controls specific to the project — aligned to organisational governance\n• Project governance includes: decision-making authority, change control, reporting requirements, acceptance criteria, stage gates\n• PMBOK 8: Governance is a full performance domain — it integrates risk, quality, change, and knowledge management"),
                s("2026 ECO — Business Environment Is Now 26% of the Exam", "The Business Environment domain tripled from 8% to 26% in the 2026 ECO. This is the single biggest change from the 2021 ECO. It now covers 8 tasks across governance, compliance, AI/sustainability, strategy alignment, and external change. Study it as seriously as you study Risk or Schedule."),
                s("2026 ECO — Business Environment Is Now 26% of the Exam", "26% means roughly 46–47 questions are from this domain (out of 180). That is almost as many as the entire People domain. Candidates who treat it as an afterthought will fail.", SectionKind.DANGER),
                s("2026 Business Environment — 8 Tasks to Know", tableHeaders = listOf("#", "Task", "What It Tests"), tableRows = listOf(listOf("1", "Evaluate & Recommend Strategy", "Align project outcomes with organisational strategy; evaluate options against strategic objectives; recommend the best-fit approach"), listOf("2", "Support Organisational Change", "Assess change readiness; plan and support change activities; manage resistance; collaborate with change management teams"), listOf("3", "Manage Compliance Requirements", "Determine compliance categories (legal, regulatory, internal policy); ensure project compliance; take corrective action when non-compliant"), listOf("4", "Evaluate & Deliver Benefits & Value", "Investigate benefit realisation mechanisms; ensure project is delivering intended business value; monitor value throughout"), listOf("5", "Evaluate & Address External Business Environment Changes", "Survey external environment (market, regulatory, political, economic); assess impact on project; update plans accordingly"), listOf("6", "Support Organisational Governance", "Identify and prioritise governance rules and policies; align project with governance framework; escalate governance issues"), listOf("7", "Integrate Project Planning Activities", "Consolidate project plans across all domains; ensure integrated baseline; use outputs from one plan as inputs to others"), listOf("8", "Manage and Implement AI/Technology in the Project Environment", "Evaluate AI tools for PM use; apply AI to planning, risk, and reporting; ensure responsible and ethical AI use; address AI-related risks"))),
                s("AI in Project Management (2026 ECO — New Topic)", "AI is formally part of the Business Environment domain in the 2026 ECO. Expect questions on:"),
                s("AI in Project Management (2026 ECO — New Topic)", tableHeaders = listOf("AI Application", "What the PM Does"), tableRows = listOf(listOf("AI-assisted risk identification", "Use AI tools to scan project data for emerging risks; validate AI outputs with expert judgment"), listOf("AI for schedule optimisation", "Leverage AI to model schedule scenarios; still applies human judgment for final decisions"), listOf("AI in reporting & dashboards", "Use AI to generate real-time performance dashboards; ensure data accuracy and integrity"), listOf("Responsible AI use", "Ensure AI decisions are explainable, fair, unbiased; follow organisational AI policy; document AI usage"), listOf("AI-related risks", "Identify risks of AI adoption (data quality, bias, dependency, regulatory); add to risk register"), listOf("Prompt engineering", "Use AI prompts as a project communication and analysis skill (formalised in PMBOK 8)"))),
                s("AI in Project Management (2026 ECO — New Topic)", "PMI's AI stance: AI augments the PM — it does not replace PM judgment. Always validate AI outputs. Always document AI usage. Ethical and responsible AI is required, not optional.", SectionKind.KEY),
                s("Sustainability in Projects (2026 ECO)", tableHeaders = listOf("Aspect", "What It Means in Practice"), tableRows = listOf(listOf("Environmental", "Assess and minimise carbon footprint, waste, and resource consumption in project activities"), listOf("Social", "Consider community impacts, diversity and inclusion, worker welfare, and stakeholder wellbeing"), listOf("Economic", "Ensure long-term value creation; avoid short-term gains that create long-term organisational or societal costs"), listOf("PM Action", "Include sustainability goals in business case; raise sustainability risks in the risk register; report on sustainability metrics alongside schedule and cost"))),
                s("Benefits Realisation — 2026 Extended Focus", "The 2026 ECO places much greater emphasis on benefits realisation throughout the project and beyond closure:"),
                s("Benefits Realisation — 2026 Extended Focus", tableHeaders = listOf("Phase", "Benefits Activity"), tableRows = listOf(listOf("Initiating", "Business case defines expected benefits; Benefits Management Plan drafted; sponsor confirms benefits ownership"), listOf("Planning", "Benefits metrics and measurement mechanisms defined; benefits realisation timeline established"), listOf("Executing", "Track early benefit signals; ensure deliverables align with intended benefits; communicate benefits progress"), listOf("Closing", "Verify benefits have been or will be realised; transition to operations with benefits tracking in place"), listOf("Post-Project", "Operations team monitors and reports on benefits; PM may support benefits review if engaged"))),
                s("Organisational Change Management (2026 — Expanded)", "Change management is now an explicit Business Environment task. The PM must:"),
                s("Organisational Change Management (2026 — Expanded)", tableHeaders = listOf("Step", "Action"), tableRows = listOf(listOf("Assess Readiness", "Evaluate organisational capacity to absorb the change; identify resistance hotspots"), listOf("Plan Change Activities", "Develop change management approach; coordinate with HR, communications, and leadership teams"), listOf("Manage Resistance", "Identify root causes of resistance; address concerns proactively; build coalitions of support"), listOf("Monitor Adoption", "Track change adoption metrics; adjust approach based on feedback; report adoption status"))),
                s("Organisational Change Management (2026 — Expanded)", "Exam Tip: When a question mentions organisational change — always look for answers that involve assessing readiness FIRST, then planning, then managing resistance. Never jump straight to implementing change.", SectionKind.TIP),
                s("External Environment Monitoring", "The PM must continuously monitor the external environment and adapt the project accordingly:"),
                s("External Environment Monitoring", tableHeaders = listOf("External Factor", "PM Response"), tableRows = listOf(listOf("New legislation or regulation", "Update Risk Register → assess compliance impact → adjust project plans → ensure compliance"), listOf("Market changes", "Re-evaluate business case value → assess impact on project benefits → engage sponsor"), listOf("Political/economic shifts", "Identify risks and opportunities → update risk register → adapt procurement and resource strategies"), listOf("Competitor moves", "Assess strategic relevance of project → engage sponsor → consider scope adjustment if needed"), listOf("Technology disruption", "Evaluate impact on project approach → assess AI/tool adoption opportunities → update tailoring decisions"))),
                s("Business Case — Components", tableHeaders = listOf("Section", "Content"), tableRows = listOf(listOf("Business Need", "What problem or opportunity is being addressed? Why now?"), listOf("Situation Analysis", "Current state; root cause; gap between current and desired state"), listOf("Options Analysis", "Alternative solutions considered (including \"do nothing\")"), listOf("Recommended Solution", "Chosen option with rationale"), listOf("Financial Analysis", "NPV, ROI, payback, BCR, total cost of ownership"), listOf("Risks", "Major risks of proceeding and NOT proceeding"), listOf("Benefits", "Expected tangible and intangible benefits (links to Benefits Management Plan)"), listOf("Success Criteria", "How success will be measured"))),
                s("Business Case — Components", "The Sponsor owns the Business Case. The PM references it throughout the project to ensure the project still delivers the intended value. If the business case becomes invalid — the PM must escalate.", SectionKind.KEY),
                s("Strategic Alignment", "Every project should trace to organisational strategy. The PM must be able to articulate this chain:\n\nOrganisational Vision\n\nStrategic Objectives\n\nPortfolio\n\nDeliverables\n\n• Mission: Why the organisation exists\n• Vision: Where the organisation wants to be\n• Strategy: How it will get there\n• Portfolio: The collection of initiatives to execute strategy\n• Project: A single initiative delivering specific outputs toward strategy"),
                s("Compliance Categories", tableHeaders = listOf("Category", "Examples", "PM Responsibility"), tableRows = listOf(listOf("Legal/Regulatory", "Data protection (GDPR), safety (OSHA), industry (FDA, SOX)", "Must comply — no exceptions; add to risk register; audit"), listOf("Organisational Policy", "Procurement rules, security policies, HR policies", "Follow; tailor within policy bounds"), listOf("Contractual", "SLA terms, delivery obligations, IP rights", "Track and report; ensure vendor compliance too"), listOf("Standards", "ISO 9001, PMI standards, industry standards", "Apply where required or beneficial"), listOf("Ethical", "PMI Code of Ethics", "Always applies regardless of local practice"), listOf("Sustainability", "ESG reporting, environmental regulations (new in 2026)", "Report and manage sustainability compliance"))),
                s("Organisational Change Management Models", tableHeaders = listOf("Model", "Steps / Concept", "Use"), tableRows = listOf(listOf("ADKAR", "Awareness → Desire → Knowledge → Ability → Reinforcement", "Individual-level change; identifying where someone is stuck"), listOf("Kotter's 8 Steps", "Urgency → Coalition → Vision → Communicate → Empower → Short-term wins → Consolidate → Anchor", "Organisational-level change"), listOf("Lewin's Model", "Unfreeze → Change → Refreeze", "Simple three-phase framework"), listOf("Bridges' Transition", "Ending → Neutral Zone → New Beginning", "Emotional/psychological side of change"))),
                s("Organisational Change Management Models", "ADKAR is the most tested change model. If a stakeholder knows about the change (Awareness) but does not want it (no Desire) — address the WHY, not the HOW. Do not jump to Knowledge/training when the barrier is Desire.", SectionKind.TIP),
                s("Knowledge Transfer and Organisational Learning", tableHeaders = listOf("Type", "Description", "How to Transfer"), tableRows = listOf(listOf("Explicit Knowledge", "Can be written down — procedures, data, manuals", "Documentation, databases, training materials"), listOf("Tacit Knowledge", "Experience-based; hard to articulate — intuition, judgment", "Mentoring, shadowing, communities of practice, storytelling"))),
                s("Knowledge Transfer and Organisational Learning", "• Lessons learned should be captured THROUGHOUT the project, not just at closure\n• Knowledge transfer to operations must happen BEFORE the team disbands\n• PMBOK 8: Manage Project Knowledge is a Governance process — it is a formal responsibility\n• Communities of practice, wikis, and post-implementation reviews support organisational learning"),
            )
        ),
        Chapter(
            "benefits",
            "📈 Benefits Realisation & Value Metrics",
            "Beyond the Triple Constraint",
            "Business & tailoring",
            listOf(
                s("Key", "The 2026 ECO and PMBOK 8 move project success from \"on time, on budget, in scope\" to \"delivered value and realised benefits.\" This section covers how value is defined, measured, and tracked — a Business Environment (26%) core topic.", SectionKind.KEY),
                s("Beyond the Triple Constraint", tableHeaders = listOf("Traditional Metric", "Limitation", "Value-Based Alternative"), tableRows = listOf(listOf("Schedule variance", "Says nothing about whether the output matters", "Time-to-value; benefit realisation date"), listOf("Cost variance", "Under budget on a worthless deliverable is still failure", "ROI; NPV; cost per unit of value delivered"), listOf("Scope completion", "100% scope of the wrong thing", "Outcome achievement; adoption rate; customer satisfaction"), listOf("Quality (defects)", "Zero defects in an unused product", "Fitness for use; NPS; support ticket reduction"))),
                s("Value Delivery Chain", "Activities"),
                s("Value Delivery Chain", tableHeaders = listOf("Level", "Definition", "Example (Customer Portal Project)", "Who Measures"), tableRows = listOf(listOf("Outputs", "What the project produces", "Portal deployed; 40 features live", "Project team"), listOf("Outcomes", "Changes that outputs enable", "60% of customers use self-service instead of calling", "Project team + operations"), listOf("Benefits", "Measurable gains from outcomes", "Call centre costs down 35%; CSAT up 12 points", "Benefits owner (business)"), listOf("Value", "Net worth to the organisation and stakeholders", "\$2.4M annual savings; improved brand reputation", "Sponsor / portfolio"))),
                s("Benefits Register", "Companion to the Benefits Management Plan — tracks each benefit through its lifecycle:"),
                s("Benefits Register", tableHeaders = listOf("Field", "Content"), tableRows = listOf(listOf("Benefit ID & Name", "B-01: Reduced call centre volume"), listOf("Type", "Tangible / Intangible; Financial / Non-financial"), listOf("Baseline", "Current state measurement before the project (e.g., 50,000 calls/month)"), listOf("Target", "Expected future state (e.g., 32,500 calls/month — 35% reduction)"), listOf("Metric & Measurement Method", "Monthly call volume from ACD system"), listOf("Timeframe", "Realisation begins Month 3 post-launch; full realisation Month 9"), listOf("Owner", "Head of Customer Operations (NOT the PM — benefits outlive the project)"), listOf("Dependencies", "Marketing campaign to drive portal adoption; staff retraining"), listOf("Status", "Planned / In Progress / Realised / At Risk / Not Realised"), listOf("Disbenefits", "Potential negative consequences — e.g., 15 call centre roles eliminated"))),
                s("Value Stream Mapping", "A Lean technique that visualises every step from request to delivered value, exposing waste and delay:"),
                s("Value Stream Mapping", tableHeaders = listOf("Element", "Definition"), tableRows = listOf(listOf("Value-Added Time (VA)", "Time spent on activities the customer would pay for"), listOf("Non-Value-Added Time (NVA)", "Waiting, handoffs, rework, approvals that add no customer value"), listOf("Lead Time", "Total elapsed time from request to delivery (VA + NVA)"), listOf("Process Cycle Efficiency (PCE)", "VA Time ÷ Lead Time × 100%"), listOf("Current State Map", "How value flows today — usually reveals PCE of 5–15%"), listOf("Future State Map", "Redesigned flow with waste removed"))),
                s("Value Stream Mapping", "Process Cycle Efficiency"),
                s("OKRs — Objectives and Key Results", "A goal-setting framework increasingly used to link projects to strategic outcomes. Structure: one qualitative Objective, 2–5 measurable Key Results.\n\nObjective: Make self-service the preferred support channel\n\nKR1: Increase portal monthly active users from 12,000 to 45,000\n\nKR2: Reduce call centre volume by 35%\n\nKR3: Achieve portal CSAT score of 4.3/5 or higher\n\nKR4: Cut average issue resolution time from 48h to 8h\n\nHow the project links: The Customer Portal project delivers the OUTPUTS; the OKRs measure whether OUTCOMES are achieved. A project can hit 100% scope and 0% OKRs — that is a failed project by PMBOK 8 standards."),
                s("OKRs — Objectives and Key Results", tableHeaders = listOf("OKR Principle", "Application"), tableRows = listOf(listOf("Ambitious", "Key results should be stretch targets — 70% achievement is considered success"), listOf("Measurable", "Every KR has a number; no \"improve\" or \"enhance\" without a metric"), listOf("Time-bound", "Typically quarterly; reviewed and re-set"), listOf("Transparent", "Visible across the organisation; aligned top-down and bottom-up"), listOf("Outcome-focused", "KRs measure results, not activities (\"reduce churn 10%\" not \"launch retention campaign\")"))),
                s("Value Metrics Toolkit", tableHeaders = listOf("Metric", "Formula / Definition", "Use"), tableRows = listOf(listOf("NPV", "Σ (Cash Flowt ÷ (1+r)t) − Initial Investment", "Project selection; accounts for time value of money"), listOf("ROI", "(Net Benefit − Cost) ÷ Cost × 100%", "Simple return comparison"), listOf("Payback Period", "Time until cumulative benefits = cumulative costs", "Cash-flow risk; shorter = less risk"), listOf("BCR", "PV Benefits ÷ PV Costs", ">1 = viable"), listOf("Time-to-Value", "Elapsed time from project start to first realised benefit", "Agile/incremental delivery justification"), listOf("Net Promoter Score (NPS)", "% Promoters − % Detractors", "Customer value perception"), listOf("Adoption Rate", "Users actively using ÷ Target users × 100%", "Whether outputs became outcomes"), listOf("Cost of Delay (CoD)", "Value lost per unit time of delay", "Prioritisation (WSJF = CoD ÷ Job Size)"), listOf("Customer Lifetime Value (CLV)", "Revenue per customer × retention period", "Product/feature value"), listOf("Total Cost of Ownership (TCO)", "Acquisition + Operation + Maintenance + Disposal", "True cost comparison across options"))),
                s("Benefits Realisation Roles", tableHeaders = listOf("Role", "Responsibility"), tableRows = listOf(listOf("Sponsor", "Accountable for the business case and overall benefits; approves Benefits Management Plan"), listOf("Benefits Owner", "Business-side individual accountable for realising and reporting a specific benefit — usually operations, not the PM"), listOf("Project Manager", "Ensures outputs enable outcomes; tracks leading indicators during the project; hands over with benefits tracking in place"), listOf("PMO / Portfolio", "Aggregates benefits across projects; validates strategic contribution; audits realisation"), listOf("Operations", "Sustains the change; measures and reports realised benefits post-project"))),
                s("Benefits Realisation Roles", "Exam trap: \"Who is accountable for benefits realisation after the project closes?\" → NOT the PM. It is the Benefits Owner / Sponsor / Operations. The PM's accountability ends at handover with tracking mechanisms in place.", SectionKind.WARN),
                s("Leading vs. Lagging Value Indicators", "Leading Indicators (predict future value)\n • Pilot user adoption rate\n• Early customer feedback / NPS on increments\n• Feature usage analytics during beta\n• Stakeholder engagement level\n• Sprint velocity trend\n• Defect escape rate"),
                s("Lagging Indicators (confirm value delivered)", "• Revenue increase\n• Cost reduction realised\n• Market share change\n• Customer retention rate\n• Regulatory compliance achieved\n• Annual ROI"),
                s("Lagging Indicators (confirm value delivered)", "Track LEADING indicators during the project so you can course-correct. Wait for LAGGING indicators only and you find out too late.", SectionKind.TIP),
            )
        ),
        Chapter(
            "ai",
            "🤖 AI in Project Management — Governance & Application",
            "PMI's Position on AI — The Mental Model",
            "Business & tailoring",
            listOf(
                s("Danger", "\"Manage and implement AI and emerging technology\" is a dedicated Business Environment task in the 2026 ECO. AI also appears in PMBOK 8 as a competency, a communication skill (prompting), and an EEF. Expect 4–8 questions.", SectionKind.DANGER),
                s("PMI's Position on AI — The Mental Model", tableHeaders = listOf("Principle", "What It Means"), tableRows = listOf(listOf("AI augments, never replaces", "AI supports PM judgment; the PM remains the accountable decision-maker"), listOf("Validate everything", "AI outputs are inputs to human review — never final outputs"), listOf("Transparency", "Disclose AI use to stakeholders; document which artifacts were AI-assisted"), listOf("Ethics first", "Bias, privacy, IP, and fairness constraints apply — PMI Code of Ethics governs AI use"), listOf("Fit for purpose", "Use AI where it adds value (pattern analysis, drafting, forecasting); not where human relationships matter (conflict, negotiation, motivation)"), listOf("Governance required", "AI use follows organisational AI policy; if none exists, the PM should propose one"))),
                s("AI Use Cases by Performance Domain", tableHeaders = listOf("Domain", "AI Application", "PM Guardrail"), tableRows = listOf(listOf("Governance", "Automated status report drafting; decision log summarisation; portfolio dashboards", "PM reviews every report before distribution; AI cannot approve changes"), listOf("Scope", "Requirements extraction from documents; user story generation; gap analysis", "Stakeholders validate; AI-generated requirements are drafts"), listOf("Schedule", "Predictive schedule analytics; critical path risk simulation; resource-levelling optimisation", "Compare AI forecasts with team estimates; investigate divergence"), listOf("Finance", "EVM anomaly detection; cost forecasting; spend pattern analysis", "Finance team validates; AI cannot authorise spend"), listOf("Stakeholders", "Sentiment analysis of communications; meeting transcription and action extraction; personalised communication drafting", "Never automate sensitive or conflict-related communication; consent for recording"), listOf("Resources", "Skill-matching; capacity forecasting; onboarding chatbots", "Check for bias in allocation; human makes assignment decisions"), listOf("Risk", "Automated risk identification from project data; Monte Carlo at scale; early-warning pattern detection", "AI-identified risks go through normal qualitative analysis; PM owns the register"))),
                s("Automated Risk Modelling — How It Works", "Historical project data\n\nAI pattern analysis\n\nRisk candidates surfaced\n\nPM + team qualitative review\n\nRisk register updated\n\nContinuous monitoring"),
                s("Automated Risk Modelling — How It Works", tableHeaders = listOf("Capability", "Description", "Limitation"), tableRows = listOf(listOf("Pattern detection", "Identifies risk signatures from thousands of past projects (e.g., \"vendor onboarding >30 days correlates with 60% schedule slip\")", "Only knows past patterns; misses novel risks"), listOf("Early warning", "Flags anomalies in real-time data (velocity drop, cost spike, communication silence)", "False positives; needs threshold tuning"), listOf("Probabilistic simulation", "Runs Monte Carlo on schedule and cost with thousands of scenarios in seconds", "Garbage in, garbage out — depends on input quality"), listOf("Natural language risk extraction", "Reads meeting notes, emails, and status reports to surface risks people mentioned", "Privacy concerns; misinterprets tone/context"))),
                s("Predictive Schedule Analytics", "• What it does: Uses historical duration data, current velocity, and dependency analysis to forecast completion dates with confidence intervals\n• Output: \"72% probability of finishing by 15 Nov; 90% by 3 Dec\" — not a single date\n• PM action: Communicate committed dates at appropriate confidence (typically 80–90%); use the gap between P50 and P90 to size schedule reserve\n• Guardrail: Team estimates remain primary; AI forecast is a cross-check. If they diverge significantly — investigate why before trusting either"),
                s("AI-Generated Documentation — Ethical Constraints", tableHeaders = listOf("Constraint", "Rule", "Rationale"), tableRows = listOf(listOf("Disclosure", "Mark AI-assisted artifacts; do not present as purely human-authored", "Honesty (PMI Code)"), listOf("Accountability", "PM signs off; PM is accountable for accuracy", "Responsibility (PMI Code)"), listOf("Confidentiality", "Do not input confidential, personal, or client data into external AI tools without authorisation", "Data protection law; Respect for property rights"), listOf("IP & Copyright", "Verify AI output does not reproduce copyrighted material; check licence terms of AI tool", "Respect (property rights); legal compliance"), listOf("Hallucination check", "Verify every fact, figure, citation, and calculation", "AI invents plausible-sounding falsehoods"), listOf("Bias review", "Check AI recommendations affecting people (resourcing, performance) for discriminatory patterns", "Fairness (PMI Code)"), listOf("Regulatory", "In regulated industries, confirm AI-generated documents meet audit and traceability requirements", "Compliance task (Business Environment)"))),
                s("AI Governance Framework for Projects", tableHeaders = listOf("Element", "Questions to Answer"), tableRows = listOf(listOf("Policy", "Which AI tools are approved? What data can be used? Who approves new tools?"), listOf("Roles", "Who is accountable for AI outputs? Who reviews for bias? Who owns the AI risk?"), listOf("Transparency", "How is AI use disclosed to stakeholders, customers, regulators?"), listOf("Data", "What data feeds the AI? Is it authorised, accurate, unbiased? Who owns it?"), listOf("Validation", "What is the human review process for each AI output type?"), listOf("Monitoring", "How is AI performance and drift tracked? When is it re-evaluated?"), listOf("Risk", "AI-specific risks in the risk register: model failure, vendor lock-in, regulatory change, skill dependency"))),
